(1, 'Conseq Prague Open, ITF W75 v hale', 2026, 2, '2026-02-08', '2026-02-15', '', '', 'pevná hala, kurty P1 a P2', 'Turnaj', 'Druhý ročník halového turnaje žen kategorie ITF W75 na Štvanici. Titul získala hráčka klubu Tereza Martincová, která prošla z kvalifikace.', '', '', '', '', 0, '', NULL, NULL, '', 1, 0, '2026-10-01 23:46:39', '2026-10-01 23:46:39'),
(2, 'Klubový den – čtyřhry, barbecue, kvíz', 2026, 5, '2026-05-24', NULL, '', '', 'areál klubu', 'Klubová akce', 'Čtyřhry ve výkonnostních skupinách, podvečerní barbecue a hospodský kvíz.', '', '', '', '', 1, '', NULL, NULL, '', 1, 1, '2026-10-01 23:46:39', '2026-10-01 23:46:39'),
(3, 'Valná hromada', 2026, 6, '2026-06-25', NULL, '', '18:00', 'klubová restaurace', 'Klub', 'Valná hromada I. ČLTK Praha.', '', '', '', '', 0, '', NULL, NULL, '', 1, 2, '2026-10-01 23:46:39', '2026-10-01 23:46:39'),
(4, 'Letní dětské kempy, 6 termínů', 2026, 7, '2026-06-29', '2026-08-28', '', '', 'areál klubu', 'Tenisová škola', 'Šest pětidenních kempů pro děti zhruba od 4 do 9 let – celodenní i dopolední varianta, oběd a pitný režim v ceně.', '', '', 'letni-kempy.php', 'Letní kempy', 0, '', NULL, NULL, '', 1, 3, '2026-10-01 23:46:39', '2026-10-01 23:46:39'),
(5, 'Sekyra Group Prague Open, 26. ročník', 2026, 8, '2026-08-16', '2026-08-22', '', '', 'antukové kurty Štvanice', 'Turnaj', 'Turnaj ATP Challenger 75 a ITF W50 na antuce, pořádaný klubem se společností Perinvest. Vstup zdarma.', '', '', 'prague-open.php', 'Prague Open', 0, '', NULL, NULL, '', 1, 4, '2026-10-01 23:46:39', '2026-10-01 23:46:39'),
(6, 'Klubový den', 2026, 9, '2026-09-06', NULL, '', '', 'areál klubu', 'Klubová akce', 'Čtyřhry ve výkonnostních skupinách, podvečerní barbecue a hospodský kvíz.', '', '', '', '', 1, '', NULL, NULL, '', 1, 5, '2026-10-01 23:46:39', '2026-10-01 23:46:39'),
(7, 'Zimní sezóna v halách', 2026, 10, '2026-10-05', '2027-04-04', 'přetlakové haly od 5. 10.', '', 'přetlakové haly a pevná hala', 'Areál', 'Přetlakové haly od 5. 10. 2026, pevná hala (kurty P1, P2) už od 28. 9. 2026. Zimní sezóna potrvá do 4. 4. 2027.', '', '', 'cenik-kurtu.php', 'Ceník kurtů', 0, '', NULL, NULL, '', 1, 6, '2026-10-01 23:46:39', '2026-10-01 23:46:39'),
(8, 'Tenisová škola podle zimních rozvrhů', 2026, 10, NULL, NULL, 'potvrzeno', '', '', 'Tenisová škola', 'Tréninky Tenisové školy podle zimních rozvrhů od 29. 9. 2026 do 2. 4. 2027.', '', '', 'tenisova-skola-rozvrhy.php', 'Rozvrhy', 0, '', NULL, NULL, '', 1, 7, '2026-10-01 23:46:39', '2026-10-01 23:46:39'),
(9, 'CTC U14 – I. ČLTK Praha Cup', 2026, 11, NULL, NULL, '', '', '', 'Centenary Tennis Clubs', 'Od roku 2008 se na Štvanici koná mezinárodní přátelské utkání dětí U14 v rámci asociace Centenary Tennis Clubs. Akce se zúčastní španělský Real Club de Tenis Barcelona, irský Carrickmines a belgický Royal Léopold Club.', '', '', 'ctc.php', 'Centenary Tennis Clubs', 0, '', NULL, NULL, 'Ověřit s klubem název belgického klubu („Royal Léopold Club“ – v PDF „Real club de Leopold“) a termín.', 1, 8, '2026-10-01 23:46:39', '2026-10-01 23:46:39'),
(10, 'Mikulášská besídka', 2026, 12, NULL, NULL, '', '', 'klubová restaurace', 'Klubová akce', 'Mikuláš, čert a anděl, básničky a sladkosti pro děti.', '', '', '', '', 0, '', NULL, NULL, 'Termín doplnit. Loni čt 4. 12. 2025 od 16:30 v klubové restauraci, přihlášky na pecha@cltk.cz.', 1, 9, '2026-10-01 23:46:39', '2026-10-01 23:46:39'),
(11, 'Večer talentů a Vánoční večírek v Letenském zámečku', 2026, 12, NULL, NULL, '', '', 'Letenský zámeček', 'Klubová akce', 'Ocenění mladých hráčů klubu, shrnutí sezóny a předání Cen ankety Jaroslava Drobného.', '', '', '', '', 1, '', NULL, NULL, 'Termín doplnit. Loni Večer talentů 11. 12. 2025 a Vánoční večírek 12. 12. 2025 od 19:00.', 1, 10, '2026-10-01 23:46:39', '2026-10-01 23:46:39'),
(12, 'OSTRA Tenisová extraliga', 2026, 12, NULL, NULL, '', '', '', 'Závodní tenis', 'Mistrovství republiky smíšených družstev. I. ČLTK Praha hraje semifinálovou skupinu.', '', '', '', '', 0, '', NULL, NULL, 'Termín doplnit.', 1, 11, '2026-10-01 23:46:39', '2026-10-01 23:46:39');
