(1, 'areal', 'casy', 'Provoz', 'Otevírací <em>doby</em>', 'Časy jednotlivých služeb. Další doplní klub.', '', '', '', '', '', '', '', 0, 1, 10, '2026-10-01 23:46:44'),
(2, 'areal', 'uzavirky', 'Uzávěrky', 'Plánované <em>uzávěrky</em>', 'Kdy je areál nebo jeho část uzavřená kvůli turnajům a akcím.', '<ul><li><strong>20.–26. 7. 2026</strong> Livesport Prague Open (WTA 250)</li><li><strong>1.–2. 8. 2026</strong> Oktagon 92 – od 14:00 uzavřeny šatny a&nbsp;fitness, od 10:00 vnitřní parkoviště a&nbsp;oblouky viaduktu; vše opět přístupné 2. 8. od 10:00</li><li><strong>16.–22. 8. 2026</strong> Sekyra Group Prague Open 2026</li><li><strong>1.–8. 10. 2026</strong> Klubová restaurace uzavřena</li></ul>', '', '', '', '', '', '', 0, 1, 11, '2026-10-01 23:46:44'),
(3, 'areal', 'sluzby', 'Služby v areálu', 'Všechno na jednom <em>ostrově</em>.', 'Bazén, wellness, fitness, fyzioterapie, restaurace Tiebreak s terasou, tenis shop, beach volejbal i firemní akce – pár minut od centra Prahy.', '', '', '', '', '', '', '', 0, 1, 12, '2026-10-01 23:46:44'),
(4, 'areal', 'letecky-leto', '', 'Léto shora', '', '', 'bloky/areal-letecky-leto.jpg', 'Léto shora: antukové kurty, bazén a centrální dvorec', '', '', '', '', 0, 1, 13, '2026-10-01 23:46:44'),
(5, 'areal', 'letecky-zima', '', 'Zima shora', '', '', 'bloky/areal-letecky-zima.jpg', 'Zima shora: přetlakové haly nad kurty a centrálním dvorcem', '', '', '', '', 0, 1, 14, '2026-10-01 23:46:44'),
(6, 'cenik-kurtu', 'ceniky', 'Léto a zima', 'Ceny za hodinu i za <em>sezónu</em>.', '', '', '', '', '', '', '', '', 0, 1, 10, '2026-10-01 23:46:44'),
(7, 'cenik-kurtu', 'kalkulacka', 'Kalkulačka', 'Kolik stojí <em>hodina</em>.', 'Vyberte sezónu, kurty, čas a formu. Přepínač „Jsem člen klubu“ ukáže členskou cenu a kolik ušetříte.', '', '', '', '', '', '', '', 0, 1, 11, '2026-10-01 23:46:44'),
