(9, 'cenik-kurtu', 'rezervace', 'Rezervace', 'Kurt si zarezervujete <em>online</em>.', 'V rezervačním systému klubu, nebo na recepci po telefonu i e-mailem.', '', '', '', '', '', '', '', 0, 1, 13, '2026-10-01 23:46:44'),
(10, 'privatni-treneri', 'treneri', 'Trenéři', 'Trenéři pro <em>rekreační</em> hráče.', '', '', '', '', '', '', '', '', 0, 1, 10, '2026-10-01 23:46:44'),
(11, 'privatni-treneri', 'kontakt', '', 'Ceny a <em>kontakt</em>', 'Ceny hodin a kontakty na jednotlivé trenéry doplní klub.', '', '', '', '', '', '', '', 1, 1, 11, '2026-10-01 23:46:44'),
(12, 'body-solution', 'kontakt', '', 'Kontakt a <em>objednání</em>', 'Kontakt, ordinační hodiny a způsob objednání doplní klub.', '', '', '', '', '', '', '', 1, 1, 10, '2026-10-01 23:46:44'),
(13, 'sportovni-lekarstvi', 'kontakt', '', 'Kontakt a <em>objednání</em>', 'Kontakt, ordinační hodiny a způsob objednání doplní klub.', '', '', '', '', '', '', '', 1, 1, 10, '2026-10-01 23:46:44'),
(14, 'prague-open', 'rocnik', 'Ročník 2026', 'Sekyra Group Prague Open 2026 by Advantage Cars', '', '<ul><li><strong>Termín</strong> 16.–22. 8. 2026</li><li><strong>Kategorie</strong> ATP Challenger 75 (muži) a&nbsp;ITF World Tennis Tour W50 (ženy)</li><li><strong>Povrch</strong> antuka</li><li><strong>Dotace</strong> muži 97 640 EUR, ženy 40 000 USD</li><li><strong>Vstup</strong> zdarma</li><li><strong>Pořadatel</strong> I.&nbsp;Český Lawn-Tennis Klub Praha a&nbsp;společnost Perinvest</li></ul>', '', '', '', '', '', '', 0, 1, 10, '2026-10-01 23:46:44'),
(15, 'prague-open', 'historie', 'Historie turnaje', 'Prague Open na <em>Štvanici</em>.', 'Od roku 2001 se turnaj hraje znovu na Štvanici a od tohoto roku klub počítá ročníky.', '<ul><li><strong>1991–1999</strong> Prague Challenger na Štvanici – první ročník vyhrál Jan Kodeš ml.</li><li><strong>Od 2001</strong> ECM Cup, ECM Prague Open (2003–2008), Advantage Cars Prague Open (2013–2019), I.ČLTK Prague Open (2020–2022), Advantage Cars Prague Open (2023–2025), od 2026 Sekyra Group Prague Open</li><li><strong>Vítězové</strong> mj. Sjeng Schalken 2003, Jan Hernych 2004, 2005 a&nbsp;2008, Diego Schwartzman 2014, Stan Wawrinka 2020, Jiří Veselý 2024, Filip Misolic 2025 a&nbsp;Jan Kumstát 2026</li><li><strong>Ženy</strong> WTA ECM Prague Open 2005–2010 (mj. Safinová 2005, Zvonarevová 2008), od 2011 turnaj ITF – Lucie Hradecká 2011, Markéta Vondroušová 2017 (finále s&nbsp;Karolínou Muchovou 7:5, 6:1)</li></ul><p>Přehled podle Wikipedie a&nbsp;klubových zpráv.</p>', 'bloky/prague-open-2026-stadion.jpg', 'Centrální dvorec během Sekyra Group Prague Open 2026 · foto fotogalerie klubu', '', '', '', '', 0, 1, 11, '2026-10-01 23:46:44'),
(16, 'kontakt', 'lide', 'Lidé a kontakty', 'Na koho se <em>obrátit</em>.', '', '', '', '', 'vedeni.php', 'Výkonný výbor a vedení klubu', '', '', 0, 1, 10, '2026-10-01 23:46:44'),
(17, 'kontakt', 'prijezd', 'Adresa a příjezd', 'Jak se k nám <em>dostanete</em>', '', '', '', '', '', '', '', '', 0, 1, 11, '2026-10-01 23:46:44'),
(18, 'kontakt', 'fakturace', 'Fakturační údaje', 'Fakturační údaje a <em>účty</em>', '', '', '', '', '', '', '', '', 0, 1, 12, '2026-10-01 23:46:44'),
(19, 'kontakt', 'dokumenty', 'Dokumenty', 'Dokumenty ke <em>stažení</em>', '', '', '', '', '', '', '', '', 0, 1, 13, '2026-10-01 23:46:44'),
(20, 'klub', 'cisla', 'Klub v číslech', '', '', '<ul><li><strong>1893</strong> rok založení – nejstarší tenisový klub v&nbsp;Praze</li><li><strong>1901</strong> na ostrově Štvanice – tehdy pět kurtů, dřevěná klubovna a&nbsp;restaurace</li><li><strong>19&nbsp;kurtů</strong> v&nbsp;areálu Štvanice, v&nbsp;zimě 12 krytých</li><li><strong>10</strong> grandslamových titulů v&nbsp;barvách klubu v&nbsp;den triumfu</li><li><strong>1 ze 3</strong> sportovních center mládeže ČTS v&nbsp;Česku, s&nbsp;celou pyramidou TSM, SVT a&nbsp;SCM</li><li><strong>1 jediný</strong> český člen Centenary Tennis Clubs – sdružení 98 klubů starších 100&nbsp;let</li></ul>', '', '', '', '', '', '', 0, 1, 3, '2026-10-01 23:46:45'),
(21, 'klub', 'prameny', '', 'Odkud čísla bereme', '', '<ol><li>Národní muzeum – inventář pozůstalosti J. Rösslera-Ořovského; ceskytenis.info.</li><li>Ústav dějin umění AV ČR – Umělecké památky, Tenisový dvorec na Štvanici.</li><li>Web klubu: tenisové kurty a&nbsp;podmínky členství. Počet zahrnuje velký centrální dvorec, který patří Českému tenisovému svazu.</li><li>Registr ČTS a&nbsp;en.wikipedia. Včetně čtyřhry a&nbsp;mixu. Podle klubové definice „hráčů Štvanice“ je titulů 20 – viz <a href=\"historie.php#sin-slavy\">Zlatou desku</a>.</li><li>ČTS, Seznam hráčů SCM/SVT/TSM 2026.</li><li>Seznam členů Centenary Tennis Clubs; web klubu 2026.</li></ol>', '', '', '', '', '', '', 0, 1, 4, '2026-10-01 23:46:45'),
(22, 'klub', 'ostrov', 'Ostrov Štvanice', '', '', '', 'bloky/klub-stvanice-panorama.jpg', 'Ostrov Štvanice s tenisovým areálem uprostřed Vltavy', '', '', '', '', 0, 1, 5, '2026-10-01 23:46:45'),
(23, 'klub', 'cesta', 'Cesta na Štvanici', '', 'Podle cs Wikipedie (Lichner 1985); klubové prameny se v prvních krocích liší.', '<ul><li><strong>1893</strong> Židovský ostrov</li><li><strong>1894</strong> Střelecký ostrov</li><li><strong>1895/96</strong> Holešovice-Bubny</li><li><strong>1901</strong> Štvanice</li></ul>', '', '', '', '', '', '', 0, 1, 6, '2026-10-01 23:46:45'),
(24, 'klub', 'rozcestnik', 'Klub', 'Členství, historie a <em>lidé</em> klubu.', '', '', '', '', '', '', '', '', 0, 1, 7, '2026-10-01 23:46:45'),
(25, 'clenstvi', 'konfigurator', 'Ceník 2026', 'Spočítejte si <em>členství</em>', 'Zvolte, kdo bude hrát – cenu spočítáme podle ceníku členství. Volbu pak přenesete do přihlášky.', '', '', '', '', '', '', '', 0, 1, 6, '2026-10-01 23:46:45'),
(26, 'clenstvi', 'clensky-list', '', 'Členský list', 'Po přijetí si Členský list vytisknete. Jeho podobu schvaluje klub.', '', '', '', '', '', '', '', 0, 1, 7, '2026-10-01 23:46:45'),
(27, 'clenstvi', 'dekujeme', 'Přihláška odeslána', 'Děkujeme, přihláška <em>dorazila</em>.', 'Přihlášku posoudí Výkonný výbor, zpravidla na nejbližším zasedání. Ozveme se vám e-mailem nebo telefonicky s dalším postupem a platebními údaji.', '', '', '', '', '', '', '', 0, 1, 8, '2026-10-01 23:46:45'),
(28, 'historie', 'linka', 'Wimbledonská linka · finále dvouhry hráčů Štvanice', '', 've štvanické historii, bez ohledu na klub v den finále', '<ul><li><strong>1954</strong> Jaroslav Drobný · vítěz</li><li><strong>1962</strong> Věra Suková-Pužejová · finále, první československá finalistka</li><li><strong>1973</strong> Jan Kodeš · vítěz</li><li><strong>2023</strong> Markéta Vondroušová · vítězka</li><li><strong>2026</strong> Karolína Muchová · finále s&nbsp;Lindou Noskovou 2:6, 7:5, 3:6</li></ul>', '', '', '', '', '', '', 0, 1, 11, '2026-10-01 23:46:45'),
(29, 'historie', 'deska-prameny', '', '', 'Prameny: seznamy klubu, registr ČTS, Revue 01/2023. Co tvrdí jen klub, nese štítek „podle klubu“.', '', '', '', '', '', '', '', 0, 1, 12, '2026-10-01 23:46:45'),
(30, 'vedeni', 'prezident', 'Prezident klubu', '', '', '', '', '', '', '', '', '', 0, 1, 2, '2026-10-01 23:46:45'),
(31, 'vedeni', 'vybor', 'Výkonný výbor', 'Výkonný <em>výbor</em>', '', '', '', '', '', '', '', '', 0, 1, 3, '2026-10-01 23:46:45'),
(32, 'vedeni', 'kancelar', 'Kancelář klubu', 'Kancelář <em>klubu</em>', 'Členství, stálé rezervace a provoz areálu.', '', '', '', '', '', '', '', 0, 1, 4, '2026-10-01 23:46:45'),
