(35, 'ctc', 'clenstvi', 'Členství v CTC', 'Sdružení klubů starších <em>sta let</em>.', '', '', '', '', '', '', '', '', 0, 1, 2, '2026-10-01 23:46:45'),
(36, 'ctc', 'foto', '', '', '', '', 'bloky/ctc-senior-2025.jpg', 'CTC Senior Competition 2025', '', '', '', '', 0, 1, 3, '2026-10-01 23:46:45'),
(37, 'ctc', 'utkani', 'Na Štvanici', 'Mezinárodní <em>utkání</em>.', 'Kluby sdružené v Centenary Tennis Clubs se navzájem zvou k přátelským utkáním.', '', '', '', '', '', '', '', 0, 1, 4, '2026-10-01 23:46:45'),
(38, 'ctc', 'souteze', 'Soutěže', 'Poháry pro děti i <em>seniory</em>.', '', '', '', '', '', '', '', '', 0, 1, 5, '2026-10-01 23:46:45'),
(39, 'revue', 'kiosek', 'Kiosek', '', 'Hledejte v titulcích obálek a v obsazích čísel, nebo sledujte příběh v obálkách.', '', '', '', '', '', '', '', 0, 1, 2, '2026-10-01 23:46:45'),
(40, 'revue', 'pribehy', '', 'Příběh v obálkách', '', '<ul><li>Karolína Muchová</li><li>Lucie Hradecká</li><li>Jan Kodeš</li><li>Nikola Bartůňková</li><li>Markéta Vondroušová</li></ul>', '', '', '', '', '', '', 0, 1, 3, '2026-10-01 23:46:45');
INSERT IGNORE INTO cltk_bloky (id, stranka, klic, stitek, nadpis, perex, text, foto, foto_popisek, odkaz, odkaz_text, odkaz2, odkaz2_text, doplni_klub, visible, poradi, updated_at) VALUES
(41, 'zavodni-tenis', 'pyramida-skola', '3–9 let', 'Tenisová škola', 'Tenisová škola Markéty Vondroušové – minitenis, střední kurt a babytenis. Nábory jsou vždy na jaře a na podzim.', '<ul><li><strong>Dětí</strong> kolem stovky (podle klubu)</li><li><strong>Vedoucí trenér</strong> Mgr. Jan Pecha, Ph.D.</li></ul>', '', '', 'tenisova-skola.php', 'Tenisová škola', '', '', 0, 1, 10, '2026-10-01 23:46:45'),
(42, 'zavodni-tenis', 'pyramida-tsm', '10–14 let', 'TSM', 'Tréninkové středisko mládeže Českého tenisového svazu.', '<ul><li><strong>Hráčů</strong> 14 + 2</li><li><strong>Hlavní trenér</strong> Bc. Antonín Štěpánek</li><li><strong>Trenéři</strong> Ing. Jaroslav Jandus, Magdaléna Zemanová</li></ul>', '', '', '', '', '', '', 0, 1, 11, '2026-10-01 23:46:45'),
(43, 'zavodni-tenis', 'pyramida-svt', '15–18 let', 'SVT', 'Středisko vrcholového tenisu ČTS – jedno ze šesti v Česku.', '<ul><li><strong>Hráčů</strong> 16 + 2</li><li><strong>Hlavní trenér</strong> Daniel Vaněk</li><li><strong>Trenéři</strong> Ing. Jan Vacek, Milan Trněný</li></ul>', '', '', '', '', '', '', 0, 1, 12, '2026-10-01 23:46:45'),
(44, 'zavodni-tenis', 'pyramida-scm', '15–21 let', 'SCM', 'Sportovní centrum mládeže ČTS, nejvyšší stupeň přípravy. V Česku jsou jen tři: I. ČLTK Praha, TK Sparta Praha a TK Prostějov.', '<ul><li><strong>Hráčů</strong> 9 + 2</li><li><strong>Hlavní trenér</strong> Zdeněk Kubík (podle ČTS)</li><li><strong>Vedoucí SCM</strong> Petr Vaníček, sportovní ředitel (podle klubu)</li><li><strong>Trenéři</strong> Ing. Jan Vacek, Milan Trněný</li></ul>', '', '', '', '', '', '', 0, 1, 13, '2026-10-01 23:46:45'),
(45, 'zavodni-tenis', 'pyramida-vrchol', 'Dospělí', 'Extraliga, WTA a ATP', 'Mistr republiky v extralize smíšených družstev 2018 a 2019. Hráčky a hráči klubu na okruzích WTA, ATP a ITF.', '<ul><li><strong>Kapitáni</strong> Petr Vaníček a&nbsp;Ivo Minář</li></ul>', '', '', '#extraliga', 'Extraliga', '', '', 0, 1, 14, '2026-10-01 23:46:45'),
(46, 'zavodni-tenis', 'zebricky', '', 'Žebříček ČTS', 'Pořadí hráčů klubu v žebříčcích dospělých · léto 2026', '<h3>Ženy</h3><ul><li><strong>1.</strong> Karolína Muchová</li><li><strong>6.</strong> Markéta Vondroušová</li><li><strong>9.</strong> Nikola Bartůňková</li><li><strong>10.</strong> Darja Viďmanová</li></ul><h3>Muži</h3><ul><li><strong>10.</strong> Jonáš Forejtek</li><li><strong>17.</strong> Jakub Nicod</li><li><strong>18.</strong> Tadeáš Paroulek</li><li><strong>19.</strong> Andrew Paulson</li></ul><p>Pramen: žebříčky Českého tenisového svazu, léto 2026.</p>', '', '', '', '', '', '', 0, 1, 20, '2026-10-01 23:46:45'),
(47, 'zavodni-tenis', 'reprezentanti', '', 'Reprezentanti 2026', 'Ze 146 reprezentantů České republiky jich 26 hraje za I. ČLTK Praha – víc mají jen TK Prostějov a TK Sparta Praha. Čtyři v kategorii do 14 let, deset do 18 let a dvanáct mezi dospělými.', '<h3>Dospělí</h3><ul><li>Nikola Bartůňková</li><li>Anastasia Detiuc</li><li>Sarah Melany Fajmonová</li><li>Karolína Muchová</li><li>Darja Viďmanová</li><li>Markéta Vondroušová</li><li>Radek Chodora</li><li>Jakub Filip</li><li>Matyáš Kozlovský</li><li>Jakub Nicod</li><li>Oliver Sanders</li><li>Matěj Vocel</li></ul>', '', '', '', '', '', '', 0, 1, 21, '2026-10-01 23:46:45'),
(48, 'zavodni-tenis', 'hraci', 'Naši hráči', 'Hráčky a hráči v sezóně <em>2026</em>.', 'Pořadí v žebříčku Českého tenisového svazu platí pro léto 2026, kariérní maxima ve světovém žebříčku WTA k uvedenému datu.', '', '', '', '', '', '', '', 0, 1, 30, '2026-10-01 23:46:45'),
(49, 'zavodni-tenis', 'hrac-muchova', '1. v žebříčku ČTS žen · léto 2026', 'Karolína Muchová', 'Za I. ČLTK Praha hraje od sezóny 2019. Kariérní maximum WTA č. 6 (13. 7. 2026).', '<ul><li>US Open 2026 – vítězka smíšené čtyřhry s&nbsp;Jakubem Menšíkem</li><li>finále Wimbledonu 2026</li><li>tituly WTA 1000 Dauhá a&nbsp;WTA 500 Bad Homburg 2026</li><li>finále Roland Garros 2023</li></ul>', 'bloky/hrac-muchova.jpg', 'Karolína Muchová s talířem pro finalistku Wimbledonu 2026', '', '', '', '', 0, 1, 31, '2026-10-01 23:46:45'),
(50, 'zavodni-tenis', 'hrac-vondrousova', '6. v žebříčku ČTS žen · léto 2026', 'Markéta Vondroušová', 'Na Štvanici od roku 2006, za I. ČLTK Praha od sezóny 2011. Čestná členka klubu, Tenisová škola nese její jméno.', '<ul><li>Wimbledon 2023 – první nenasazená šampionka v&nbsp;historii</li><li>stříbro na olympijských hrách v&nbsp;Tokiu (hráno 2021)</li><li>finále Roland Garros 2019</li><li>WTA 500 Berlín 2025</li></ul>', 'bloky/hrac-vondrousova.jpg', 'Markéta Vondroušová s mísou Venus Rosewater Dish · Wimbledon 2023', '', '', '', '', 0, 1, 32, '2026-10-01 23:46:45'),
(51, 'zavodni-tenis', 'hrac-bartunkova', '9. v žebříčku ČTS žen · léto 2026', 'Nikola Bartůňková', 'I. ČLTK Praha je její domovský oddíl, v klubu hraje od roku 2017. Kariérní maximum WTA č. 34 (14. 9. 2026).', '<ul><li>3. kolo Australian Open 2026 z&nbsp;kvalifikace</li><li>semifinále WTA 500 Guadalajara 2025</li><li>finále WTA 125 Samsun 2025</li><li>finále juniorského Wimbledonu 2023</li></ul>', 'bloky/hrac-bartunkova.jpg', 'Nikola Bartůňková na Australian Open 2026', '', '', '', '', 0, 1, 33, '2026-10-01 23:46:45'),
(52, 'zavodni-tenis', 'hrac-vidmanova', '10. v žebříčku ČTS žen · léto 2026', 'Darja Viďmanová', 'Štvanická hráčka od juniorských let, za I. ČLTK Praha od roku 2014. V elitní stovce WTA od 22. 6. 2026, kariérní maximum č. 75 (31. 8. 2026).', '<ul><li>první titul WTA – WTA 125 Figueira da Foz 2026</li><li>finále WTA 250 Memphis 2026</li></ul>', 'bloky/hrac-vidmanova.jpg', 'Darja Viďmanová ve finále turnaje WTA 250 v Memphisu', '', '', '', '', 0, 1, 34, '2026-10-01 23:46:45'),
(53, 'zavodni-tenis', 'hrac-martincova', '20. v žebříčku ČTS žen · léto 2026', 'Tereza Martincová', 'V klubu od roku 2011, mistryně extraligy 2018 a 2019. Kariérní maximum WTA č. 40 (únor 2022).', '<ul><li>Conseq Prague Open 2026 (ITF W75) – titul z&nbsp;kvalifikace, v&nbsp;hale na Štvanici</li></ul>', 'bloky/hrac-martincova.jpg', 'Tereza Martincová s trofejí z Conseq Prague Open 2026', '', '', '', '', 0, 1, 35, '2026-10-01 23:46:45'),
(54, 'zavodni-tenis', 'hrac-forejtek', '10. v žebříčku ČTS mužů · léto 2026', 'Jonáš Forejtek', 'Odchovanec klubu – za I. ČLTK Praha hrál v letech 2012–2018 a znovu hraje od roku 2022.', '<ul><li>juniorská světová jednička (2019, tehdy za TK Škoda Plzeň)</li><li>vítěz juniorského US Open 2019</li><li>čtyřhra ATP Challenger 125 Sevilla 2025</li></ul>', '', '', '', '', '', '', 0, 1, 36, '2026-10-01 23:46:45'),
(55, 'zavodni-tenis', 'extraliga-rocniky', 'Ročníky extraligy', '', '', '<ul><li><strong>2025</strong> 2. místo ve skupině (se Spartou 1:5, s&nbsp;Plíšková Tennis Academy 6:3)</li><li><strong>2024</strong> 3.–4. místo</li><li><strong>2023</strong> vyhrané předkolo, 2. místo ve skupině</li><li><strong>2022</strong> poslední místo ve skupině</li><li><strong>2021</strong> dělené 3. místo</li><li><strong>2020</strong> 2. místo ve skupině (se Spartou 3:6)</li><li><strong>2019</strong> <em>mistr České republiky</em> – finále 18. 12. v&nbsp;Říčanech, s&nbsp;Přerovem 5:2</li><li><strong>2018</strong> <em>mistr České republiky</em> – finále 19. 12. v&nbsp;Říčanech, s&nbsp;Prostějovem 5:4, první titul po 28 letech</li><li><strong>2015</strong> finalista – finále s&nbsp;Prostějovem 0:6</li><li><strong>2011</strong> finalista – finále s&nbsp;Prostějovem 2:5</li></ul>', '', '', '', '', '', '', 0, 1, 40, '2026-10-01 23:46:45'),
(56, 'zavodni-tenis', 'soupiska', 'Soupiska 2025', 'Družstvo v extralize <em>2025</em>', 'Kapitáni týmu Petr Vaníček a Ivo Minář.', '<h3>Ženy</h3><ul><li>Karolína Muchová</li><li>Markéta Vondroušová</li><li>Nikola Bartůňková</li><li>Darja Viďmanová</li><li>Tereza Martincová</li><li>Sarah Melany Fajmonová</li></ul><h3>Muži</h3><ul><li>Jonáš Forejtek</li><li>Tadeáš Paroulek</li><li>Jakub Nicod</li><li>Andrew Paulson</li><li>Jakub Filip</li><li>Matěj Vocel</li></ul>', 'bloky/extraliga-2025-tym.jpg', 'Družstvo I. ČLTK Praha v Tenisové extralize 2025 · foto Martin Sidorják', 'https://tenisovaextraliga.cz/soupisky/', 'Celá soupiska na tenisovaextraliga.cz', '', '', 0, 1, 41, '2026-10-01 23:46:45'),
(57, 'zavodni-tenis', 'druzstva', 'Družstva mládeže', 'Medaile z mistrovství <em>republiky</em>', 'Klub hraje soutěže družstev ve všech věkových kategoriích – od babytenisu a středního kurtu přes žactvo a dorost po dospělé.', '<h3>Sezóna 2026</h3><ul><li><strong>Babytenis</strong> MČR družstev – 2. místo z&nbsp;12 (Prostějov, 4.–6. 9.)</li><li><strong>Starší žactvo</strong> MČR družstev – 3. místo (Ostrava, 28.–30. 8.)</li><li><strong>Mladší žactvo</strong> MČR družstev – 3. místo z&nbsp;8 (Zlín, 8.–11. 7.)</li><li><strong>Dorost</strong> MČR družstev – 3. místo (TK Sparta Praha, 9.–12. 9.)</li></ul><h3>Sezóna 2025</h3><ul><li><strong>Dorost</strong> vicemistr České republiky – finále se Spartou 2:5</li><li><strong>Starší žactvo</strong> MČR družstev – 3. místo (Rakovník)</li><li><strong>Pražská liga</strong> starší i&nbsp;mladší žactvo – 1. místo</li></ul>', '', '', '', '', '', '', 0, 1, 50, '2026-10-01 23:46:45'),
(58, 'tenisova-skola', 'informace', 'Informace', 'Jak škola <em>funguje</em>', '', '', '', '', '', '', '', '', 0, 1, 2, '2026-10-01 23:46:45'),
(59, 'tenisova-skola', 'kategorie', 'Kategorie podle věku', 'Minitenis, střední kurt a <em>babytenis</em>', 'Tenisová škola každoročně pořádá turnaje pro hráče do 9 let. Přihlášky na turnaje jsou v informačním systému Českého tenisového svazu.', '<ul><li><strong>Minitenis</strong> do 7&nbsp;let (podle ročníku narození)</li><li><strong>Střední kurt</strong> do 8&nbsp;let</li><li><strong>Babytenis</strong> do 9&nbsp;let</li></ul>', '', '', '', '', '', '', 0, 1, 3, '2026-10-01 23:46:45'),
(60, 'tenisova-skola', 'prihlaska', 'Přihláška', 'Jak se do školy <em>přihlásit</em>', 'Nábory jsou vždy na jaře a na podzim.', '<ol><li><strong>Nábor</strong> vždy na jaře a&nbsp;na podzim</li><li><strong>Domluva</strong> s&nbsp;vedoucím trenérem Tenisové školy – telefonicky nebo e-mailem</li><li><strong>Členství</strong> základní členství Tenisové školy 1&nbsp;000&nbsp;Kč, hradí se na začátku roku</li><li><strong>Tréninky</strong> podle rozvrhů skupin, cena zahrnuje trenéra i&nbsp;pronájem kurtu</li></ol>', '', '', '', '', '', '', 0, 1, 4, '2026-10-01 23:46:45'),
(61, 'tenisova-skola-rozvrhy', 'harmonogram', 'Harmonogram', 'Termíny <em>sezóny</em>', 'Tréninky, prázdniny a dny, kdy se nehraje. Změny vyhrazeny.', '', '', '', '', '', '', '', 0, 1, 2, '2026-10-01 23:46:45'),
(62, 'letni-kempy', 'terminy', 'Termíny', 'Termíny <em>kempů</em>', 'Pětidenní kempy ve dvou variantách – celodenní (A) a dopolední (B).', '', '', '', '', '', 'https://cltk.dphoto.com/album/o54c6s0a', 'Fotogalerie kempů 2026', 0, 1, 2, '2026-10-01 23:46:45'),
(63, 'letni-kempy', 'ceny', 'Ceník', 'Varianty a <em>ceny</em>', 'Ceny za pětidenní kemp. Hráči I. ČLTK Praha mají cenu zvýhodněnou.', '', '', '', '', '', '', '', 0, 1, 3, '2026-10-01 23:46:45'),
(64, 'letni-kempy', 'prihlaska', 'Přihláška', 'Přihláška a <em>kontakt</em>', 'Přihlašuje se online formulářem. Platí se až po potvrzení přihlášky e-mailem.', '', '', '', '', '', '', '', 0, 1, 4, '2026-10-01 23:46:45'),
(65, 'index', 'uvod', 'Ostrov Štvanice, Praha 7', 'Tenis na ostrově uprostřed Prahy od roku <em>1893</em>.', '', '', '', '', 'clenstvi.php', 'Stát se členem', 'cenik-kurtu.php', 'Ceník kurtů', 0, 1, 0, '2026-10-01 23:46:45'),
(66, 'index', 'aktuality', 'Aktuality z klubu', '', '', '', '', '', '', '', '', '', 0, 1, 1, '2026-10-01 23:46:45'),
(67, 'index', 'vysledky', 'Aktuální výsledky našich hráčů', '', '', '', '', '', '', '', '', '', 0, 1, 2, '2026-10-01 23:46:45'),
(68, 'index', 'kalendar', 'Klubový kalendář', 'Na Štvanici se <em>potkáváme</em>.', 'Klubový rok – vyberte událost', '', '', '', '', '', '', '', 0, 1, 3, '2026-10-01 23:46:45'),
(69, 'index', 'clenstvi', '', 'Členem se může stát <em>každý</em>.', '', '', 'bloky/clenstvi-vstup-cedule.jpg', 'Vstup do areálu I. Českého Lawn-Tennis Klubu Praha', 'clenstvi.php', 'Stát se členem', '', '', 0, 1, 4, '2026-10-01 23:46:45'),
(70, 'index', 'sluzby', 'Služby v areálu', '', '', '', '', '', '', '', '', '', 0, 1, 5, '2026-10-01 23:46:45'),
(71, 'index', 'historie', 'Naše historie', '', '', '', '', '', 'historie.php', 'Kompletní historie', '', '', 0, 1, 6, '2026-10-01 23:46:45'),
(72, 'index', 'partneri', 'Partneři', '', '', '', '', '', '', '', '', '', 0, 1, 7, '2026-10-01 23:46:45'),
(73, 'klub', 'uvod', 'Klub', 'Nejstarší tenisový klub v&nbsp;<em>Praze</em>.', 'I. Český Lawn-Tennis Klub Praha byl založen v roce 1893 a na ostrově Štvanice sídlí od roku 1901. V klubu paralelně funguje závodní i rekreační tenis a členem se může stát každý.', '', '', '', 'clenstvi.php', 'Stát se členem', 'historie.php', 'Historie klubu', 0, 1, 0, '2026-10-01 23:46:45'),
(74, 'klub', 'o-klubu', '', 'Klub uprostřed <em>města</em>', '', '<p>Areál na ostrově Štvanice nabízí 19 tenisových kurtů – v&nbsp;létě 13 venkovních antukových a&nbsp;3 s&nbsp;tvrdým povrchem, k&nbsp;tomu 2&nbsp;kurty v&nbsp;pevné hale a&nbsp;velký centrální dvorec. V&nbsp;zimě je pod halami 12 krytých kurtů.</p><p>Klub je jediným českým členem sdružení Centenary Tennis Clubs, které spojuje tenisové kluby starší 100&nbsp;let, a&nbsp;v&nbsp;adresáři Českého tenisového svazu je veden jako klub č. 52.</p>', '', '', '', '', '', '', 0, 1, 1, '2026-10-01 23:46:45'),
(75, 'klub', 'jmena', 'Pět jmen, jeden klub', 'Pět jmen, jeden <em>klub</em>.', '', '<ul><li><strong>1893</strong> I.&nbsp;Český Lawn-Tennis Klub</li><li><strong>1949</strong> oddíl pod Sokol Jinonice, později TJ Motorlet</li><li><strong>kolem 1956</strong> Spartak Praha Motorlet</li><li><strong>kolem 1969</strong> TJ Dopravní podnik</li><li><strong>1990</strong> I.&nbsp;ČLTK Praha</li></ul><p>Roky změn jmen uvádíme podle klubu, prameny se v&nbsp;nich liší.</p>', '', '', '', '', '', '', 0, 1, 2, '2026-10-01 23:46:45'),
(76, 'clenstvi', 'uvod', 'Členství 2026', 'Členem se může stát <em>každý</em>.', 'Členství v klubu I. ČLTK Praha je nabízeno široké veřejnosti a není podmíněno žádnými dodatečnými kritérii. O přijetí rozhoduje Výkonný výbor, zpravidla na nejbližším zasedání.', '', '', '', '#prihlaska', 'Vyplnit přihlášku', '', '', 0, 1, 0, '2026-10-01 23:46:45'),
(77, 'clenstvi', 'v-cene', '', 'V ceně členství', '', '<ul><li>venkovní kurty v&nbsp;letní sezóně zdarma – 13 antukových (3 s&nbsp;osvětlením) a&nbsp;3 tvrdé</li><li>venkovní bazén s&nbsp;travnatou plochou</li><li>fitness centrum</li><li>regenerace: vířivka, sauna, infrasauna, odpočívárna</li><li>beach volejbal a&nbsp;multifunkční hřiště (zdarma, hrají-li jen členové)</li><li>klubové akce: celosezónní soutěž pro rekreační hráče, klubové dny, mikulášská besídka, vánoční večírek, golfový turnaj</li><li>klubový časopis I.ČLTK Revue (2× ročně) a&nbsp;dvouměsíčník I.ČLTK Newsletter, i&nbsp;v&nbsp;angličtině</li><li>hra zdarma v&nbsp;klubech Centenary Tennis Clubs po doporučení generálního manažera</li></ul>', '', '', '', '', '', '', 0, 1, 1, '2026-10-01 23:46:45'),
(78, 'clenstvi', 'zvyhodneni', '', 'Výhody členů v zimě', '', '<ul><li>přednostní rezervace 12 krytých kurtů</li><li>zvýhodněné ceny hodin i&nbsp;celé zimní sezóny</li><li>sleva v&nbsp;klubovém shopu</li><li>pronájem venkovního dvorce pro hosta 100&nbsp;Kč/hod</li><li>host do fitness nebo k&nbsp;bazénu 400&nbsp;Kč/den</li></ul>', '', '', '', '', '', '', 0, 1, 2, '2026-10-01 23:46:45'),
(79, 'clenstvi', 'postup', '', 'Jak se stát <em>členem</em>', '', '<ol><li><strong>Žádost</strong> – přihláška až pro pět osob; u&nbsp;osob mladších 15&nbsp;let údaje a&nbsp;souhlas zákonného zástupce, právnická osoba přikládá výpis z&nbsp;rejstříku.</li><li><strong>Výkonný výbor</strong> – členství vzniká dnem jeho rozhodnutí, zpravidla na nejbližším zasedání.</li><li><strong>Platba</strong> – v&nbsp;kanceláři (Eva Štefková, Po–Pá 9:00–17:00), na recepci nebo převodem na účet 1471509/0300, zpráva „jméno – členství“.</li><li><strong>Členská karta</strong> – hrající členové ji dostanou pro vstup do šaten a&nbsp;fitness.</li></ol>', '', '', '', '', '', '', 0, 1, 3, '2026-10-01 23:46:45'),
(80, 'clenstvi', 'druhy', '', 'Druhy členství podle stanov', '', '<ul><li><strong>Řádné</strong> – každá fyzická nebo právnická osoba.</li><li><strong>Zasloužilé</strong> – uděluje Výkonný výbor za úspěšnou sportovní reprezentaci klubu nebo dlouhodobou dobrovolnou práci pro klub.</li><li><strong>Čestné</strong> – uděluje Valná hromada za vítězství v&nbsp;grandslamové či olympijské dvouhře, také prezidentu a&nbsp;premiérovi ČR a&nbsp;primátorovi Prahy; čestní členové neplatí příspěvek.</li></ul>', '', '', '', '', '', '', 0, 1, 4, '2026-10-01 23:46:45');
INSERT IGNORE INTO cltk_bloky (id, stranka, klic, stitek, nadpis, perex, text, foto, foto_popisek, odkaz, odkaz_text, odkaz2, odkaz2_text, doplni_klub, visible, poradi, updated_at) VALUES
(81, 'clenstvi', 'prihlaska', 'Přihláška', 'Přihláška do <em>klubu</em>', 'Přihlášku posoudí Výkonný výbor. Ozveme se vám e-mailem nebo telefonicky s dalším postupem a platebními údaji.', '', '', '', '', '', '', '', 0, 1, 5, '2026-10-01 23:46:45'),
(82, 'historie', 'uvod', 'Historie', 'Od roku 1893 na ostrovech <em>Prahy</em>.', 'Založení v roce 1893, od roku 1901 Štvanice, tři wimbledonští vítězové, kteří tu vyrostli, a jména, která zůstávají. Co tvrdí jen klubové prameny, označujeme „podle klubu“.', '', '', '', '', '', '', '', 0, 1, 0, '2026-10-01 23:46:45'),
(83, 'historie', 'triptych', 'Tři wimbledonské trávy', 'Tři vítězové Wimbledonu vyrostli <em>na Štvanici</em>.', '1954, 1973 a 2023. V den titulu hrála v barvách klubu jen vítězka posledního z nich – i to patří k poctivé historii.', '', '', '', '', '', '', '', 0, 1, 1, '2026-10-01 23:46:45'),
(84, 'historie', 'kronika', 'Kronika', 'Kronika <em>Štvanice</em>.', 'Epochy nesou přibližné roky – data změn názvu klubu se v pramenech liší.', '', '', '', '', '', '', '', 0, 1, 2, '2026-10-01 23:46:45'),
(85, 'historie', 'deska', 'Síň slávy', 'Jména, která <em>zůstávají</em>.', 'Klubové texty počítají úspěchy všech, kdo na Štvanici vyrostli. Registr Českého tenisového svazu jen tituly v barvách klubu. Na desce ukazujeme obojí.', '', '', '', '', '', '', '', 0, 1, 3, '2026-10-01 23:46:45'),
(86, 'historie', 'deska-grandslam', '', 'Grand Slam', 'Klub počítá tituly všech, kdo na Štvanici vyrostli, kdykoli za klub hráli nebo jsou čestnými či zasloužilými členy: 20 titulů, z toho 7 ve dvouhře.', '<p>Registr ČTS: jen tituly hráčů, kteří v&nbsp;den triumfu hráli za I.&nbsp;ČLTK Praha – 10 titulů. Registr začíná rokem 1996, starší tituly v&nbsp;barvách klubu jsou jen pravděpodobné.</p>', '', '', '', '', '', '', 0, 1, 4, '2026-10-01 23:46:45'),
(87, 'historie', 'deska-cestni', '', 'Čestní členové', 'Čestné členství uděluje Valná hromada – za vítězství v grandslamové či olympijské dvouhře, prezidentu a premiérovi ČR a primátorovi Prahy.', '<p>Historičtí čestní členové od roku 1893. Roky udělení doplní klub.</p>', '', '', '', '', '', '', 1, 1, 5, '2026-10-01 23:46:45'),
(88, 'historie', 'deska-mistri', '', 'Mistři republiky', '16 titulů mistra republiky ve smíšených družstvech (podle klubu).', '<p>Rozpis: 12× Spartak Praha Motorlet, 1975, 1990, 2018 a&nbsp;2019. Nezávisle jsou doloženy tituly 1975, 1990, 2018 a&nbsp;2019.</p>', '', '', '', '', '', '', 0, 1, 6, '2026-10-01 23:46:45'),
(89, 'historie', 'deska-oh', '', 'Olympijské hry', 'Tři olympijské medaile v barvách klubu a dvě ze štvanické historie.', '', '', '', '', '', '', '', 0, 1, 7, '2026-10-01 23:46:45'),
(90, 'historie', 'deska-zasluzili', '', 'Zasloužilí členové', '34 zasloužilých členů podle seznamu klubu.', '<p>Roky udělení a&nbsp;medailony doplní klub.</p>', '', '', '', '', '', '', 1, 1, 8, '2026-10-01 23:46:45'),
(91, 'historie', 'deska-prezidenti', '', 'Prezidenti', 'Prezidenti klubu od roku 1893 (podle klubu).', '<p>Prvních 36&nbsp;let – roky úřadu doplní klub.</p>', '', '', '', '', '', '', 1, 1, 9, '2026-10-01 23:46:45'),
(92, 'historie', 'osobnosti', 'Osobnosti klubu', 'Od Žemly po <em>Muchovou</em>.', 'Jen osobnosti s doloženou vazbou na klub. Podle registru ČTS získali hráči v barvách klubu v den triumfu 10 grandslamových titulů; tituly Drobného a Kodeše patří do štvanické historie.', '', '', '', '', '', '', '', 0, 1, 10, '2026-10-01 23:46:45'),
(93, 'vedeni', 'uvod', 'Vedení klubu', 'Kdo klub <em>vede</em>.', 'Prezidentem klubu je od 14. 7. 2022 Ing. Petr Šimůnek. Klub řídí devítičlenný Výkonný výbor, provoz zajišťuje kancelář klubu.', '', '', '', '', '', '', '', 0, 1, 0, '2026-10-01 23:46:46'),
(94, 'vedeni', 'dokumenty', '', 'Stanovy a dokumenty', 'Stanovy klubu a další dokumenty jsou ke stažení v PDF.', '', '', '', '', '', '', '', 0, 1, 1, '2026-10-01 23:46:46'),
(95, 'ctc', 'uvod', 'Centenary Tennis Clubs', 'Jediný český člen <em>stoletých</em> klubů.', 'Centenary Tennis Clubs sdružuje tenisové kluby starší 100 let. I. ČLTK Praha je členem od roku 2000 a jediným klubem z České republiky.', '', '', '', '', '', '', '', 0, 1, 0, '2026-10-01 23:46:46'),
(96, 'ctc', 'rodokmen', 'Rodokmen stoletých', '', 'Rok založení 1893 sdílí klub s Lawn Tennis de Monte-Carlo. Kdo z nich byl první, prameny neurčí – přesné datum založení I. ČLTK neuvádějí. Roky podle webů jednotlivých klubů.', '', '', '', '', '', '', '', 0, 1, 1, '2026-10-01 23:46:46'),
(97, 'revue', 'uvod', 'I.ČLTK Revue', 'Dvacet let Revue v jedné <em>poličce</em>.', '41 čísel klubového časopisu od roku 2006, dvakrát ročně. Texty Jiljí Kubec, grafika Kateřina Kuželová, hlavní fotograf Martin Sidorják. Čísla 01/2016 a 02/2016 v archivu PDF chybí.', '', '', '', '', '', '', '', 0, 1, 0, '2026-10-01 23:46:46'),
(98, 'revue', 'newslettery', 'Newsletter', 'Klubový <em>newsletter</em>.', 'Klubový dvouměsíčník od roku 2015, česky i anglicky. Editor Mgr. Jan Pecha, Ph.D.', '', '', '', '', '', '', '', 0, 1, 1, '2026-10-01 23:46:46'),
(99, 'areal', 'uvod', 'Areál a služby', 'Devatenáct kurtů, bazén a&nbsp;<em>klid</em> uprostřed Prahy.', '„Takto blízko centra Prahy naleznete jen velmi málo podobně příjemných a klidných míst…“', '', '', '', 'cenik-kurtu.php', 'Ceník kurtů', '', '', 0, 1, 0, '2026-10-01 23:46:46'),
(100, 'areal', 'kurty', '', 'Kurty v létě a v <em>zimě</em>', '', '<p><strong>Léto:</strong> 13 venkovních antukových kurtů (3 s&nbsp;umělým osvětlením – kurty 2, 3, 4), 3&nbsp;kurty s&nbsp;tvrdým povrchem (7, 8, 9), 2&nbsp;kurty v&nbsp;pevné hale (P1, P2) a&nbsp;velký centrální dvorec C.</p><p><strong>Zima:</strong> 12 krytých kurtů – 10 s&nbsp;tvrdým povrchem (C, 1, 2, 3, 4, 7, 8, 9, P1, P2) a&nbsp;2 antukové (5, 6). Kurty na Slavoji (10–16) jsou v&nbsp;zimě uzavřené.</p><p>Velký centrální dvorec patří Českému tenisovému svazu, ostatní kurty klubu.</p>', '', '', '', '', '', '', 0, 1, 1, '2026-10-01 23:46:46'),
(101, 'areal', 'plan', '', 'Plán areálu', 'Zleva: Slavoj s kurty 10–16, Negrelliho viadukt a parkoviště, hlavní budova s kurtem 1 a stadionem, bazén, kurty 5–9 a trojkurt.', '', 'bloky/plan-arealu.jpg', 'Plán areálu, verze 09-2025', 'https://files.cltk.cz/l8wemjw6xri01/Pl%C3%A1n%20are%C3%A1lu%20%2009-2025%20na%20web.pdf', 'Plán areálu v PDF', '', '', 0, 1, 2, '2026-10-01 23:46:46'),
(102, 'areal', 'prijezd', '', 'Jak se k nám <em>dostanete</em>', 'Přístup z Hlávkova mostu (tramvaj č. 14, brána pro pěší) nebo z Karlína a Holešovic po lávce HolKa. Autem na vyhrazené parkoviště u Negrelliho viaduktu a zadním vchodem do areálu.', '', '', '', '', '', '', '', 0, 1, 3, '2026-10-01 23:46:46'),
(103, 'cenik-kurtu', 'uvod', 'Ceník kurtů', 'Ceník <em>kurtů</em>.', 'Kurty si rezervujete online nebo na recepci. Členové klubu hrají v letní sezóně na venkovních kurtech zdarma.', '', '', '', 'clenstvi.php', 'Výhody členství', '', '', 0, 1, 0, '2026-10-01 23:46:46'),
(104, 'cenik-kurtu', 'pravidla', '', 'Pravidla rezervací', '', '<ul><li>Trvalé rezervace je nutné zrušit telefonicky nejpozději 24 hodin předem.</li><li>Náhrady za včas zrušené hodiny lze čerpat nejvýše 4 týdny.</li><li>Zvýhodněná cena předplatného na celé hrací období platí jen při platbě předem a&nbsp;za celé období.</li><li>Klub si vyhrazuje právo přesunout rezervaci na jiný dvorec nebo do jiné haly při zachování času a&nbsp;typu povrchu.</li></ul>', '', '', '', '', '', '', 0, 1, 1, '2026-10-01 23:46:46'),
(105, 'privatni-treneri', 'uvod', 'Privátní trenéři', 'Privátní <em>trenéři</em>.', 'Výuka tenisu pro rekreační hráče všech výkonnostních úrovní. Podrobnosti, ceny a kontakty doplní klub.', '', '', '', '', '', '', '', 1, 1, 0, '2026-10-01 23:46:46'),
(106, 'body-solution', 'uvod', 'Body Solution', 'Body <em>Solution</em>.', 'Ordinace Body Solution Clinic v areálu klubu. Podrobnosti, nabídku a kontakty doplní klub.', '', '', '', '', '', '', '', 1, 1, 0, '2026-10-01 23:46:46'),
(107, 'sportovni-lekarstvi', 'uvod', 'Sportovní lékařství', 'Sportovní <em>lékařství</em>.', 'Fyzioterapie, masáže a sportovní lékařství ve wellness centru areálu – pro závodní hráče, členy i veřejnost. Podrobnosti a kontakty doplní klub.', '', '', '', '', '', '', '', 1, 1, 0, '2026-10-01 23:46:46'),
(108, 'zavodni-tenis', 'uvod', 'Závodní tenis', 'Celá pyramida <em>závodního</em> tenisu.', 'I. ČLTK Praha je jedním ze tří klubů v Česku (se Spartou a Prostějovem), které mají celou pyramidu středisek Českého tenisového svazu: TSM, SVT a SCM.', '', '', '', '', '', '', '', 0, 1, 0, '2026-10-01 23:46:46'),
(109, 'zavodni-tenis', 'pyramida', '', 'Od školy po <em>extraligu</em>', '', '<ul><li><strong>Tenisová škola Markéty Vondroušové</strong> – 3–9&nbsp;let</li><li><strong>TSM</strong> – tréninkové středisko mládeže, 10–14&nbsp;let, hlavní trenér Antonín Štěpánek</li><li><strong>SVT</strong> – středisko vrcholového tenisu, 15–18&nbsp;let, hlavní trenér Daniel Vaněk</li><li><strong>SCM</strong> – sportovní centrum mládeže, 15–21&nbsp;let, hlavní trenér Zdeněk Kubík; vedoucím SCM je podle klubu sportovní ředitel Petr Vaníček</li><li><strong>Extraliga, WTA a&nbsp;ATP</strong></li></ul>', '', '', '', '', '', '', 0, 1, 1, '2026-10-01 23:46:46'),
(110, 'zavodni-tenis', 'cisla', '', 'Sezóna 2026 v <em>číslech</em>', '', '<ul><li>26 reprezentantů České republiky ze 146</li><li>121 hráčů v&nbsp;žebříčcích ČTS (léto 2026)</li><li>4 z&nbsp;TOP 10 českého žebříčku žen (léto 2026)</li><li>MČR družstev 2026: babytenis 2. místo, starší žactvo 3. místo, mladší žactvo 3. místo, dorost 3. místo</li></ul>', '', '', '', '', '', '', 0, 1, 2, '2026-10-01 23:46:46'),
(111, 'zavodni-tenis', 'extraliga', '', 'Extraliga smíšených <em>družstev</em>', '', '<p>Mistr ČR 2018 (finále 19. 12. v&nbsp;Říčanech, Prostějov 5:4 – první titul po 28 letech) a&nbsp;2019 (finále 18. 12., Přerov 5:2). Finalista 2011 a&nbsp;2015. Kapitáni týmu Petr Vaníček a&nbsp;Ivo Minář.</p>', '', '', '', '', '', '', 0, 1, 3, '2026-10-01 23:46:46'),
(112, 'zavodni-tenis-treneri', 'uvod', 'Trenérský tým', 'Trenéři <em>závodního</em> tenisu.', 'Bývalí reprezentanti, daviscupoví hráči a trenéři, kteří vedli hráče světové špičky.', '', '', '', '', '', '', '', 0, 1, 0, '2026-10-01 23:46:46'),
(113, 'tenisova-skola', 'uvod', 'Tenisová škola', 'Tenisová škola Markéty <em>Vondroušové</em>.', 'Tenisová škola je již více než 15 let přímou součástí I. ČLTK Praha a v roce 2023 s ní spojila své jméno wimbledonská vítězka Markéta Vondroušová. Je pro děti od 3 do 9 let; nábory jsou vždy na jaře a na podzim.', '', '', '', 'tenisova-skola-ceniky.php', 'Ceník', 'letni-kempy.php', 'Letní kempy', 0, 1, 0, '2026-10-01 23:46:46'),
(114, 'tenisova-skola', 'kontakt', '', 'Kontakt', '', '<p>Mgr. Jan Pecha, Ph.D., vedoucí trenér Tenisové školy<br><a href=\"tel:+420721663118\">+420 721 663 118</a> · <a href=\"mailto:pecha@cltk.cz\">pecha@cltk.cz</a></p>', '', '', '', '', '', '', 0, 1, 1, '2026-10-01 23:46:46'),
(115, 'tenisova-skola-ceniky', 'uvod', 'Tenisová škola', 'Ceník <em>tenisové školy</em>.', 'Cena zahrnuje trenéra i pronájem kurtu. Základní členství Tenisové školy 1 000 Kč se hradí vždy na začátku roku.', '', '', '', '', '', '', '', 0, 1, 0, '2026-10-01 23:46:46'),
(116, 'tenisova-skola-rozvrhy', 'uvod', 'Tenisová škola', 'Rozvrhy a <em>harmonogram</em>.', 'Tréninky podle zimních rozvrhů od 29. 9. 2026 do 2. 4. 2027. Změny vyhrazeny.', '', '', '', '', '', '', '', 0, 1, 0, '2026-10-01 23:46:46'),
(117, 'tenisova-skola-rozvrhy', 'rozvrhy', '', 'Zimní rozvrhy skupin', 'Rozvrhy jednotlivých skupin doplní klub.', '', '', '', '', '', '', '', 1, 1, 1, '2026-10-01 23:46:46'),
(118, 'tenisova-skola-treneri', 'uvod', 'Tenisová škola', 'Trenéři <em>tenisové školy</em>.', 'Trenérský tým Tenisové školy Markéty Vondroušové.', '', '', '', '', '', '', '', 0, 1, 0, '2026-10-01 23:46:46'),
(119, 'letni-kempy', 'uvod', 'Tenisová škola', 'Letní kempy <em>2026</em>.', 'Šest pětidenních kempů od 29. 6. do 28. 8. 2026 pro děti zhruba od 4 do 9 let (minitenis, střední kurt, babytenis). Vedou je profesionální trenéři I. ČLTK Praha.', '', '', '', 'https://forms.gle/JvMQNKJJmoBareVa7', 'Přihláška na kemp', '', '', 0, 1, 0, '2026-10-01 23:46:46'),
(120, 'letni-kempy', 'informace', '', 'Co je dobré <em>vědět</em>', '', '<ul><li>Podmínkou je alespoň roční pravidelná tenisová příprava; úplní začátečníci po předchozí domluvě.</li><li><strong>Varianta A&nbsp;celodenní</strong> (8:30–16:30): 2 fáze tenisu a&nbsp;2 fáze kondiční přípravy, pro děti zhruba 5–9&nbsp;let, skupiny zpravidla po 3 až 4.</li><li><strong>Varianta B dopolední</strong> (8:30–13:30): 1 fáze tenisu, skupinový trénink, pro děti kolem 5&nbsp;let.</li><li>V&nbsp;ceně je oběd a&nbsp;pitný režim.</li><li>S&nbsp;sebou: raketa, sportovní oblečení, plavky a&nbsp;ručník, obuv na antuku a&nbsp;pevný povrch, láhev s&nbsp;nápojem, svačinka.</li><li>Platba až po potvrzení e-mailem, převodem na účet 312451935/0300, variabilní symbol = rodné číslo dítěte, zpráva: jméno a&nbsp;číslo termínu.</li></ul><p>Kontakt: Mgr. Jan Pecha, Ph.D., <a href=\"tel:+420721663118\">721 663 118</a>, <a href=\"mailto:pecha@cltk.cz\">pecha@cltk.cz</a></p>', '', '', '', '', '', '', 0, 1, 1, '2026-10-01 23:46:46');
INSERT IGNORE INTO cltk_bloky (id, stranka, klic, stitek, nadpis, perex, text, foto, foto_popisek, odkaz, odkaz_text, odkaz2, odkaz2_text, doplni_klub, visible, poradi, updated_at) VALUES
(121, 'restaurace', 'uvod', 'Restaurace', 'Restaurace <em>Tiebreak</em>.', 'Od 1. 11. se můžete těšit na novou klubovou restauraci Tiebreak. Vlastní web restaurace připravujeme.', '', 'bloky/restaurace-terasa.jpg', 'Terasa klubové restaurace', '', '', '', '', 0, 1, 0, '2026-10-01 23:46:46'),
(122, 'restaurace', 'informace', '', 'Terasa a <em>salónek</em>', '', '<p>Venkovní terasa restaurace prošla rekonstrukcí – nová terasa podle ateliéru Adama Fröhlicha má 60 míst. K&nbsp;restauraci patří salónek s&nbsp;dětským koutkem, u&nbsp;terasy je dětské hřiště. Restaurace zajistí i&nbsp;raut a&nbsp;firemní akce.</p>', '', '', '', '', '', '', 0, 1, 1, '2026-10-01 23:46:46'),
(123, 'restaurace', 'kontakt', '', 'Otevírací doba a kontakt', 'Otevírací dobu, kontakt a menu doplní klub.', '', '', '', '', '', '', '', 1, 1, 2, '2026-10-01 23:46:46'),
(124, 'prague-open', 'uvod', 'Turnaj klubu', 'Prague Open, <em>26.</em> ročník.', 'Sekyra Group Prague Open 2026 by Advantage Cars – ATP Challenger 75 a ITF W50 na antuce Štvanice, 16.–22. 8. 2026. Pořádá I. Český Lawn-Tennis Klub Praha se společností Perinvest. Vlastní web turnaje připravujeme.', '', 'bloky/prague-open-2026-antuka.jpg', '© Sekyra Group Prague Open 2026, foto Martin Sidorják a Jan Pecha', 'https://www.pragueopen.net/', 'pragueopen.net', '', '', 0, 1, 0, '2026-10-01 23:46:46'),
(125, 'prague-open', 'vitezove', '', 'Vítězové <em>2026</em>', '', '<ul><li><strong>Dvouhra mužů:</strong> Jan Kumstát – finále s&nbsp;Chun-Hsin Tsengem 5:7, 6:3, 6:0</li><li><strong>Čtyřhra mužů:</strong> Andrew Paulson (I.&nbsp;ČLTK) a&nbsp;Joran Vliegen – 6:4, 6:3</li><li><strong>Dvouhra žen:</strong> Jana Kovačková – finále s&nbsp;Xinyu Gao 6:1, 6:1</li><li><strong>Čtyřhra žen:</strong> Alena a&nbsp;Jana Kovačkovy – 6:2, 6:3</li></ul><p>Klub počítá ročníky od roku 2001. Vstup na turnaj je zdarma.</p>', '', '', '', '', '', '', 0, 1, 1, '2026-10-01 23:46:46'),
(126, 'kontakt', 'uvod', 'Kontakt', 'Kontakt a <em>příjezd</em>.', 'Ostrov Štvanice 38, 170 00 Praha 7. Recepce pro rezervace kurtů, kancelář klubu pro členství a stálé rezervace.', '', '', '', '', '', '', '', 0, 1, 0, '2026-10-01 23:46:46'),
(127, 'formulare', 'souhlas', '', 'Souhlas se zpracováním údajů', 'Souhlasím se zpracováním uvedených osobních údajů I. Českým Lawn-Tennis Klubem Praha za účelem vyřízení přihlášky.', '', '', '', '', '', '', '', 0, 1, 0, '2026-10-01 23:46:46'),
(128, '404', 'uvod', 'Chyba 404', 'Tuhle stránku jsme <em>nenašli</em>.', 'Adresa se mohla změnit nebo stránka už neexistuje. Zkuste úvodní stránku nebo menu nahoře.', '', '', '', 'index.php', 'Na úvodní stránku', '', '', 0, 1, 0, '2026-10-01 23:46:46');
INSERT IGNORE INTO cltk_ctc (id, typ, nazev, rok, misto, text, odkaz, zdroj, zvyraznit, visible, poradi) VALUES
(1, 'fakt', 'Sdružení stoletých klubů', '', '', 'Centenary Tennis Clubs sdružuje tenisové kluby starší 100 let. Vzniklo v roce 1996 pod patronací J. A. Samaranche se sídlem v Olympijském muzeu v Lausanne a dnes má 98 klubů.', 'http://www.centenarytennisclubs.com/members.htm', 'web klubu 2026; seznam členů CTC', 0, 1, 0),
(2, 'fakt', 'Jediný český člen', '2000', '', 'I. ČLTK Praha je členem od roku 2000 a jediným klubem z České republiky.', '', 'seznam členů CTC; web klubu', 0, 1, 1),
(3, 'fakt', 'Hra v klubech CTC', '', '', 'Členové klubu mohou po doporučení generálního manažera hrát zdarma v klubech sdružených v Centenary Tennis Clubs.', '', 'web klubu', 0, 1, 2),
(4, 'fakt', 'Klub ve vedení CTC', '2005', '', 'Ing. Petr Šimůnek zastupuje klub v řídícím výboru CTC od roku 2005.', '', 'web klubu', 0, 1, 3),
(5, 'klub', 'Real Club de Tenis Barcelona-1899', '', 'Barcelona', 'přátelské utkání na Štvanici', '', 'https://cltk.cz/cs/klub/ctc/', 0, 1, 0),
(6, 'klub', 'Villa Primrose', '', 'Bordeaux', 'přátelské utkání na Štvanici', '', 'https://cltk.cz/cs/klub/ctc/', 0, 1, 1),
(7, 'klub', 'Fitzwilliam LTC', '', 'Dublin', 'přátelské utkání na Štvanici', '', 'https://cltk.cz/cs/klub/ctc/', 0, 1, 2),
(8, 'klub', 'H.L.T.C. Leimonias', '', 'Haag', 'přátelské utkání na Štvanici', '', 'https://cltk.cz/cs/klub/ctc/', 0, 1, 3),
(9, 'klub', 'Carrickmines Croquet & LTC', '', 'Dublin', 'přátelské utkání na Štvanici', '', 'https://cltk.cz/cs/klub/ctc/', 0, 1, 4),
(10, 'utkani', 'All England Lawn Tennis Club na Štvanici', '2025', '', '6.–8. 6. 2025', '', 'klubový kalendář; newsletter 5/2025', 0, 1, 0),
(11, 'utkani', 'International Clubs', '2025', '', '12.–13. 6. 2025, hráči z osmi států', '', 'klubový kalendář; Revue 02/2025', 0, 1, 1),
(12, 'utkani', 'The International Lawn Tennis Club', '2026', '', '11.–12. 6. 2026', '', 'klubový kalendář', 0, 1, 2),
(13, 'soutez', 'Carrickmines Cup (U12)', '2007', '', 'Od roku 2007; soupeři z Dublinu, Barcelony, Londýna, Santanderu a Stockholmu.', '', 'web klubu', 0, 1, 0),
(14, 'soutez', 'I. ČLTK Praha Cup (U14)', '2008', '', 'Od roku 2008 mezinárodní přátelské utkání dětí U14 na Štvanici, tradičně první listopadový víkend.', 'akce.php', 'web klubu', 0, 1, 1),
