INSERT IGNORE INTO cltk_osobnosti (id, jmeno, kategorie, roky, cin, foto, fokus, alt, pramen, jistota, jistota_text, visible, poradi) VALUES
(1, 'Ladislav Žemla', 'Legenda klubu', '1887–1955', 'Bronz OH Antverpy 1920 – mix se Skrbkovou; první mistr ČSR ve dvouhře 1920.', 'osobnosti/osobnost-ladislav-zemla.jpg', '50% 8%', 'Ladislav Žemla', 'en.wikipedia – Ladislav Žemla', 'overeno', 'ověřeno', 1, 0),
(2, 'Jaroslav Drobný', 'Čestný člen', '1921–2001', 'Wimbledon 1954 – finále s Rosewallem 13-11, 4-6, 6-2, 9-7. Mistr světa v ledním hokeji 1947.', 'osobnosti/osobnost-jaroslav-drobny.jpg', '50% 6%', 'Jaroslav Drobný s wimbledonským pohárem', 'tennisfame.com · en.wikipedia · ve štvanické historii', 'overeno', 'ověřeno', 1, 1),
(3, 'Věra Suková-Pužejová', 'Legenda klubu', '1931–1982', 'Finále Wimbledonu 1962 – první čs. finalistka. Roland Garros 1957 – mix s Javorským.', 'osobnosti/osobnost-vera-sukova-puzejova.jpg', '50% 6%', 'Věra Suková-Pužejová', 'en.wikipedia – Věra Suková', 'overeno', 'ověřeno', 1, 2),
(4, 'Pavel Korda', 'Zasloužilý člen', '1935–2019', 'Trenér daviscupového týmu ČSSR 1970–1981 (Davis Cup 1980) a trenér Jana Kodeše.', 'osobnosti/osobnost-pavel-korda.jpg', '44% 18%', 'Pavel Korda při forhendu', 'iROZHLAS/ČTK 5. 5. 2019', 'klub', 'vazba podle klubu', 1, 3),
(5, 'Ing. Jan Kodeš', 'Čestný člen', 'nar. 1946', 'Wimbledon 1973 – finále s Metrevelim 6-1, 9-8 (7-5), 6-3. Prezident klubu 1987–1990.', 'osobnosti/osobnost-ing-jan-kodes.jpg', '42% 14%', 'Jan Kodeš na Štvanici', 'tennisfame.com · ve štvanické historii', 'overeno', 'ověřeno', 1, 4),
(6, 'Lucie Hradecká', 'Zasloužilá členka', 'za I. ČLTK 2003–2023', 'Roland Garros 2011 a US Open 2013 – čtyřhra s Hlaváčkovou; stříbro OH 2012.', 'osobnosti/osobnost-lucie-hradecka.jpg', '62% 22%', 'Lucie Hradecká s pohárem z Roland Garros', 'registr ČTS · en.wikipedia', 'overeno', 'ověřeno', 1, 5),
(7, 'Markéta Vondroušová', 'Čestná členka', 'za I. ČLTK od 2011', 'Wimbledon 2023 – první nenasazená šampionka v historii (finále s Jabeurovou 6:4, 6:4).', 'osobnosti/osobnost-marketa-vondrousova.jpg', '45% 22%', 'Markéta Vondroušová s mísou Venus Rosewater Dish', 'registr ČTS · en.wikipedia · newsletter 130 let', 'overeno', 'ověřeno', 1, 6),
(8, 'Karolína Muchová', 'Hráčka klubu', 'za I. ČLTK od 2019', 'US Open 2026 – mix s Menšíkem 6:3, 1:6, [10:6]; finále Wimbledonu 2026.', 'osobnosti/osobnost-karolina-muchova.jpg', '48% 14%', 'Karolína Muchová', 'registr ČTS · usopen.org · wtatennis.com', 'overeno', 'ověřeno', 1, 7);
