INSERT IGNORE INTO cltk_price_lists (id, klic, nazev, podnazev, obdobi, poznamka_nahore, poznamka_dole, pdf_url, visible, poradi, updated_at) VALUES
(1, 'kurty-leto', 'Kurty – letní sezóna 2026', 'Cena za hodinu, celý den včetně víkendů', '', '', 'Členové klubu hrají v letní sezóně na venkovních kurtech zdarma.', '', 1, 0, '2026-10-01 23:46:40'),
(2, 'kurty-zima', 'Kurty – zimní sezóna 2026/27', 'Cena za hodinu a předplatné jedné hodiny týdně na celé období', '28. 9. 2026 – 4. 4. 2027', 'Pevná hala od 28. 9. 2026, přetlakové haly od 5. 10. 2026 do 4. 4. 2027. V zimě je k dispozici 12 krytých kurtů.', 'Zvýhodněná cena za předplatné na celé hrací období platí pouze při platbě předem a za celé období.\n\nKlub si vyhrazuje právo přesunout rezervaci na jiný dvorec nebo do jiné haly, přičemž musí dodržet rezervovaný čas a typ povrchu.\n\nTrvalé rezervace je nutné zrušit telefonicky nejpozději 24 hod předem.\n\nNáhrady za včas zrušené hodiny je možné čerpat v období maximálně 4 týdnů.', 'https://files.cltk.cz/9lawqgo4cjn01/Cen%C3%ADk%20zimn%C3%AD%20sezona%2026-27.pdf', 1, 1, '2026-10-01 23:46:40'),
(3, 'clenstvi', 'Členství 2026', 'Roční členské příspěvky', '2026', 'Členství v klubu I. ČLTK Praha je nabízeno široké veřejnosti, není podmíněno žádnými dodatečnými kritérii a členem se tak může stát úplně každý. Stačí uhradit roční členský poplatek.', 'Je určeno pro fyzické osoby a zajišťuje bezplatné využívání venkovních dvorců a všech klubových prostorů, kromě tenisových hal v zimním období. Hrající členové obdrží členské karty opravňující ke vstupu do prostorů šaten a fitness.\n\nDítě = 4–18 let nebo studující. Cena za pronájem venkovního dvorce pro nehrajícího člena je stejná jako pro veřejnost.', '', 1, 2, '2026-10-01 23:46:40'),
(4, 'skola', 'Tenisová škola – ceník', 'Cena zahrnuje trenéra i pronájem kurtu', '', 'Tréninky jsou evidovány v přehledech trenérů a v informačním systému klubu. Cena zahrnuje trenéra i pronájem kurtu.', 'Základní členství Tenisové školy 1 000 Kč (hradí se vždy na začátku roku).', '', 1, 3, '2026-10-01 23:46:40'),
(5, 'kempy', 'Letní kempy 2026', 'Pětidenní kempy pro děti zhruba od 4 do 9 let', '29. 6. – 28. 8. 2026', 'Pro děti od cca 4 do 9 let (minitenis, střední kurt, babytenis) s minimálně jednoroční pravidelnou tenisovou přípravou; úplní začátečníci po předchozí domluvě.', 'V ceně je oběd a pitný režim. Platba až po potvrzení e-mailem, převodem na účet 312451935/0300.', '', 1, 4, '2026-10-01 23:46:40'),
(6, 'doplnkove', 'Doplňkové služby', '', '', '', 'Beachvolejbalové a multifunkční hřiště je pro členy zdarma, pokud hrají jen členové; s hosty je pronájem o 25 % levnější.', '', 1, 5, '2026-10-01 23:46:40');
