INSERT IGNORE INTO cltk_sluzby (id, nazev, kotva, perex, text, fakta, foto, fokus, casy, odkaz, je_stitek, visible, poradi, created_at, updated_at) VALUES
(1, 'Recepce', 'recepce', 'Rezervace kurtů a informace o areálu.', 'Recepce rezervuje kurty po telefonu i e-mailem; online si kurt zarezervujete v rezervačním systému klubu.', 'telefon +420 608 974 974\nrecepce@cltk.cz', 'sluzby/recepce.jpg', '50% 50%', '', '', 1, 1, 0, '2026-10-01 23:46:41', '2026-10-01 23:46:41'),
(2, 'Venkovní bazén', 'bazen', 'Bazén s travnatou plochou – jen pro členy a jejich hosty.', 'Nedílná součást štvanického areálu již více než 20 let – trávník, polohovatelná lehátka a občerstvení z klubové restaurace.', 'provoz přibližně květen–září (podle počasí)\nčlenové zdarma, host člena 400 Kč/den\njen pro členy a jejich hosty', 'sluzby/bazen-lehatka-destniky.jpg', '50% 50%', 'cca květen–září', '', 1, 1, 1, '2026-10-01 23:46:41', '2026-10-01 23:46:41'),
(3, 'Fitness', 'fitness', 'Fitness centrum pro závodní i rekreační hráče.', 'Prostory otevřené v roce 2017 díky I. etapě nástavby na ochozu malého centrálního dvorce.', 'členové zdarma (s omezením během klubové kondice)\nhost člena 400 Kč\notevřeno po dobu provozu budovy', 'sluzby/fitness-centrum.jpg', '50% 50%', '', '', 1, 1, 2, '2026-10-01 23:46:41', '2026-10-01 23:46:41'),
(4, 'Regenerace a wellness', 'wellness', 'Vířivka, sauna s odpočívárnou, infrasauna a Kneippovy lázně.', 'Wellness centrum s vířivou vanou Jacuzzi, saunou s odpočívárnou, infrasaunou, Kneippovými lázněmi a ice bath (jen pro závodní hráče). Otevřeno od března 2019 díky II. etapě nástavby na ochozu malého centru.', 'všední dny 16:00–20:00, bez rezervace\njen pro členy, zdarma; rekreační členové max. 2× týdně\nkvěten–září saunu nahlásit alespoň hodinu předem', 'sluzby/wellness-virivka-lehatka.jpg', '50% 50%', 'všední dny 16:00–20:00', '', 1, 1, 3, '2026-10-01 23:46:41', '2026-10-01 23:46:41'),
(5, 'Fyzioterapie a sportovní lékařství', 'fyzioterapie', 'Fyzioterapie, masáže a sportovní lékařství přímo v areálu.', 'Prostory ve wellness centru: fyzioterapie Bc. Joseph B. Truesdale, sportovní lékařství Zdravý sport. Od června 2026 v areálu ordinuje Body Solution Clinic.', 'pro závodní hráče, členy i veřejnost', '', '50% 50%', '', 'sportovni-lekarstvi.php', 1, 1, 4, '2026-10-01 23:46:41', '2026-10-01 23:46:41'),
(6, 'Tenis shop', 'tenis-shop', 'Vyplétání raket, Mizuno, Babolat a klubový merchandising.', 'Od listopadu 2023 ve vestibulu: vyplétání raket, Mizuno, Babolat a klubový merchandising I. ČLTK.', 'kontaktní osoba Tomáš Truneček\nsleva pro členy', 'sluzby/tenis-shop.jpg', '50% 50%', 'Po–Pá 9:00–12:00 a 13:00–17:00', '', 1, 1, 5, '2026-10-01 23:46:41', '2026-10-01 23:46:41'),
(7, 'Salónek a dětský koutek', 'salonek', 'Salónek s dětským koutkem u klubové restaurace.', 'Salónek s dětským koutkem navazuje na klubovou restauraci, u terasy je dětské hřiště.', '', 'sluzby/restaurace-salonek-detsky-koutek.jpg', '50% 50%', '', '', 1, 1, 6, '2026-10-01 23:46:41', '2026-10-01 23:46:41'),
(8, 'Restaurace Tiebreak', 'restaurace', 'Klubová restaurace s venkovní terasou.', 'Klubová restaurace s venkovní terasou – nová terasa podle ateliéru Adama Fröhlicha má 60 míst. Restaurace zajistí i raut a firemní akce.', '', 'sluzby/restaurace-tiebreak-interier.jpg', '50% 50%', '', 'restaurace.php', 1, 1, 7, '2026-10-01 23:46:41', '2026-10-01 23:46:41'),
(9, 'Parkoviště', 'parkoviste', 'Vyhrazené parkoviště u Negrelliho viaduktu.', 'Pro příjezd autem je lepší po sjezdu z magistrály areál zprava objet, zaparkovat na vyhrazeném parkovišti a do areálu vejít zadním vchodem. Parkuje se i pod oblouky Negrelliho viaduktu.', '', '', '50% 50%', '', '', 1, 1, 8, '2026-10-01 23:46:41', '2026-10-01 23:46:41'),
(10, 'Beach volejbal', 'beach-volejbal', 'Beachvolejbalové hřiště v zadní části areálu.', 'Hřiště je v zadní části areálu za Negrelliho viaduktem (Slavoj); šatny a sprchy jsou v hlavní budově.', 'pronájem 400 Kč/hod\nhrají-li jen členové, zdarma; člen s hosty o 25 % levněji', 'sluzby/beachvolejbal-hriste.jpg', '50% 50%', '', '', 1, 1, 9, '2026-10-01 23:46:41', '2026-10-01 23:46:41'),
(11, 'Multifunkční hřiště (Slavoj)', 'hriste-slavoj', 'Multifunkční hřiště v zadní části areálu.', 'Hřiště je v zadní části areálu za Negrelliho viaduktem (Slavoj); šatny a sprchy jsou v hlavní budově.', 'pronájem 900 Kč/hod\nhrají-li jen členové, zdarma; člen s hosty o 25 % levněji', 'sluzby/multifunkcni-hriste.jpg', '50% 50%', '', '', 1, 1, 10, '2026-10-01 23:46:41', '2026-10-01 23:46:41'),
(12, 'Multifunkční hřiště (u trojkurtu)', 'hriste-trojkurt', 'Menší multifunkční hřiště u trojkurtu.', '', '', '', '50% 50%', '', '', 1, 1, 11, '2026-10-01 23:46:41', '2026-10-01 23:46:41'),
(13, 'Pronájem tenisových kurtů', 'kurty', 'Kurty se rezervují přes recepci nebo online; členové hrají v létě na venkovních kurtech zdarma.', 'Veřejnost si může venkovní dvorce pronajmout denně od 7:00 do 22:00.', 'členská rezervace max. týden dopředu, max. 1,5 hodiny denně, nanejvýš dvě platné rezervace, min. dvě jména\nv létě nejsou trvalé rezervace\nhrací jednotka zahrnuje úpravu dvorce', 'sluzby/kurty-antuka-stromy-leto.jpg', '50% 50%', 'denně 7:00–22:00', 'cenik-kurtu.php', 0, 1, 12, '2026-10-01 23:46:41', '2026-10-01 23:46:41'),
(14, 'Výuka tenisu', 'vyuka', 'Výuka na všech výkonnostních úrovních.', 'Tenisová škola pro děti od 3 do 9 let, závodní tenis a privátní trenéři pro rekreační hráče.', 'dětské letní kempy (6 termínů)', 'sluzby/kurt-antuka-zivy-plot-tribuny.jpg', '50% 50%', '', 'privatni-treneri.php', 0, 1, 13, '2026-10-01 23:46:41', '2026-10-01 23:46:41'),
(15, 'Firemní akce', 'firemni-akce', 'Kurty, zázemí, restaurace s terasou a doplňkové služby pro firmy.', 'Kurty, zázemí šaten i společenských prostor, restaurace s terasou a rauty, doplňkově bazén, wellness a trenéři.', 'firemní členství 40 000 Kč ročně (min. 2 přenosné klubové karty)', 'sluzby/terasa-promenada-hodiny.jpg', '50% 50%', '', '', 0, 1, 14, '2026-10-01 23:46:41', '2026-10-01 23:46:41'),
(16, 'Klubové prostory', 'klubove-prostory', 'Vestibul, klubová místnost a recepce.', 'Vestibul s velkoformátovou černobílou fototapetou, klubová místnost pro odpočinek, studium a schůzky a recepce. Ve foyer je koláž černobílých fotografií tenisových es a pamětní deska Jaroslava Drobného, odhalená 14. 6. 2012.', '', 'sluzby/klubove-prostory-lounge.jpg', '50% 50%', '', '', 0, 1, 15, '2026-10-01 23:46:41', '2026-10-01 23:46:41');
INSERT IGNORE INTO cltk_treneri (id, jmeno, role, zarazeni, skupina, foto, fokus, fakta, text, telefon, email, kontakt, visible, poradi, created_at, updated_at) VALUES
(1, 'Petr Vaníček', 'sportovní ředitel a vedoucí SCM', 'zavodni', 'Vedení', 'treneri/petr-vanicek.jpg', '50% 22%', 'trenér II. třídy\nod roku 1984 členem I.ČLTK Praha (od mládežnických družstev po národní ligu)\nod roku 1994 trenér mládeže (I.ČLTK Praha, Liechtenstein)\npůsobil jako sparingpartner bývalé první hráčky světa Martiny Hingis\nspolupracoval s úspěšnými hráči (např. Radka Bobková, David Rikl, Martin Damm, Karolína Plíšková, Andrea Hlaváčková)', '', '', '', '', 1, 0, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(2, 'Jiří Hřebec', 'trenér SVT a SCM', 'zavodni', 'Trenéři kategorie junioři a dospělí', 'treneri/jiri-hrebec.jpg', '50% 22%', 'trenér II. třídy\nbývalý československý reprezentant, top ranking 25 (19.4.1974)\nvítěz Galeova poháru (1970), účastník 17 zápasů v Davis Cupu (finalista z roku 1975)\nbývalý trenér Davis Cupu\nspolupracoval s úspěšnými hráči (např. Markéta Vondroušová, Iveta Benešová, Ivo Minář, Jan Hernych, Marek Routa, Robin Staněk, Vladislav Chramosta, Tomáš Cakl, Jaroslav Levinský)', '', '', '', '', 1, 1, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(3, 'Ivo Minář', 'trenér SVT a SCM', 'zavodni', 'Trenéři kategorie junioři a dospělí', 'treneri/ivo-minar.jpg', '50% 22%', 'bývalý hráč ATP a reprezentant, top ranking 62 (20.7.2009)\nčlen vítězného týmu Davis Cupu\nzahrál si finále turnaje okruhu ATP Tour v Sydney, kde prohrál s domácím hráčem Lleytonem Hewittem\nV roce 2000 vyhrál juniorské Mistrovství Evropy\nspolupracuje s úspěšnými hráči (např. Andrew Paulson, Jonáš Forejtek, Jakub Nicod)', '', '', '', '', 1, 2, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(4, 'Milan Trněný', 'trenér SVT a SCM', 'zavodni', 'Trenéři kategorie junioři a dospělí', 'treneri/milan-trneny.jpg', '50% 22%', 'trenér II. třídy\nbývalý hráč ATP a juniorský reprezentant\ndvojnásobný vítěz extraligy družstev, finalista Pardubické juniorky\ntop ATP ranking ve dvouhře 471 (1995), ve čtyřhře 264 (1993)\nspolupracoval s úspěšnými hráči (např. Jiří Vaněk, Michal Vrbenský)', '', '', '', '', 1, 3, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(5, 'Ing. Jan Vacek', 'trenér SVT a SCM', 'zavodni', 'Trenéři kategorie junioři a dospělí', 'treneri/jan-vacek.jpg', '50% 22%', 'trenér I. třídy\nbývalý hráč ATP a reprezentant, top ranking 61 (5.8.2002)\nna okruhu ATP Tour vyhrál jeden turnaj ve dvouhře, když triumfoval na Brasil Open 2001, na grandslamu se nejdále probojoval do čtvrtého kola ve Wimbledonu v roce 2002\nspolupracoval s úspěšnými hráči (např. Tatsuma Ito, Marco Chiudinelli, Tereza Martincová, Jan Hernych)', '', '', '', '', 1, 4, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(6, 'Daniel Vaněk', 'trenér SVT a SCM', 'zavodni', 'Trenéři kategorie junioři a dospělí', 'treneri/daniel-vanek.jpg', '50% 22%', 'trenér II. třídy\nbývalý ligový hráč a juniorský reprezentant\nspolupracoval s úspěšnými hráči (např. Roman Jebavý, Ksenia Lykina, Michaela Krajíčková, Kateřina Böhmová, Jana Lubasová)', '', '', '', '', 1, 5, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(7, 'Ing. Jaroslav Jandus', 'hlavní trenér mládeže a TSM', 'zavodni', 'Trenéři kategorie do 14 let', 'treneri/jaroslav-jandus.jpg', '50% 22%', 'trenér II. třídy\nšéftrenér I.ČLTK Praha v letech 2000-2016\nbývalý trenér Fed Cupu\nspolupracoval s úspěšnými hráči (např. Iveta Benešová, Michaela Krajíčková, Zarina Diyas, Daniela Bedáňová, Denisa Chládková, Sandra Kleinová, Jitka Schönfeldová)', '', '', '', '', 1, 6, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(8, 'Bc. Antonín Štěpánek', 'trenér mládeže a vedoucí TSM', 'zavodni', 'Trenéři kategorie do 14 let', 'treneri/antonin-stepanek.jpg', '50% 22%', 'trenér I. třídy (titul Bc. z FTVS UK v oboru Trenér)\nvystudované 2,5 roku bakalářského studia v oboru Kondiční trenér na FTVS a 1 rok v navazujícím Mgr. studiu v oboru Kondiční trenér na Masarykově Univerzitě v Brně\nnejvyšší umístění na žebříčku ATP - 1235\nmistr republiky ve dvouhře v kategorii dorost, 5x mistr republiky ve čtyřhře v kategorii dospělí\nspolupracoval s úspěšnými hráči (např. Linda Fruhvirtová)', '', '', '', '', 1, 7, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(9, 'Ing. Lubomír Štych', 'trenér mládeže a TSM', 'zavodni', 'Trenéři kategorie do 14 let', 'treneri/lubomir-stych.jpg', '50% 22%', 'trenér II. třídy\nbývalý ligový hráč\ntrenér reprezentace dívek do 14 let\nspolupracoval s úspěšnými hráči (např. Karolína Plíšková, Kristýna Plíšková, Andrea Hlaváčková, Barbora Strýcová, Petra Rohanová)', '', '', '', '', 1, 8, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(10, 'Magdaléna Zemanová', 'trenérka mládeže a TSM', 'zavodni', 'Trenéři kategorie do 14 let', 'treneri/magdalena-zemanova.jpg', '50% 22%', 'bývalá ligová hráčka\nspolupracovala s úspěšnými hráči (např. Markéta Vondroušová, Jan Šátral, Denisa Hindová, Tomáš Piskáček, Marek Routa, Robin Staněk, Filip Zeman, Kateřina Kramperová)', '', '', '', '', 1, 9, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(11, 'Mgr. Pavel Janda', 'kondiční trenér SVT a TSM', 'zavodni', 'Kondiční trenéři', 'treneri/pavel-janda.jpg', '50% 22%', 'absolvent UK FTVS\ndiplomovaný trenér I. třídy\nspolupracoval s úspěšnými hráči (např. Markéta Vondroušová, Karolína Muchová, Karolína Plíšková, Kristýna Plíšková, Lucie Hradecká, Lukáš Rosol)', '', '', '', '', 1, 10, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(12, 'Mgr. Richard Pavluv', 'kondiční trenér SCM a SVT', 'zavodni', 'Kondiční trenéři', 'treneri/richard-pavluv.jpg', '50% 22%', 'absolvent magisterského studia UK FTVS, obor TVS, specializace tenis\ntrenér I. třídy\nbývalý hráč 1. ligy\nmistr České republiky v kickboxu v kategorii fullcontact\nspolupracuje s úspěšnými hráči (Nikola Bartůňková, Jonáš Forejtek, Toby Kodat, Andrew Paulson a Jakub Nicod)', '', '', '', '', 1, 11, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(13, 'Zdeněk Kubík', 'hlavní trenér SCM při I.ČLTK Praha (dle ČTS)', 'zavodni', 'Další trenéři', '', '50% 22%', '', '', '', '', '', 1, 12, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(14, 'Lukáš Vejvara', 'trenér (starší a mladší žactvo)', 'zavodni', 'Další trenéři', '', '50% 22%', '', '', '', '', '', 1, 13, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(15, 'Mgr. Jan Pecha, Ph.D.', 'vedoucí trenér tenisové školy', 'skola', '', 'treneri/jan-pecha.jpg', '50% 22%', 'absolvent postgraduálního doktorského studia v oboru kinantropologie na UK FTVS (zaměření na dlouhodobou koncepci sportovního tréninku)\ndiplomovaný trenér ČTS\nasistent manažera klubu, člen organizačního výboru při mezinárodním turnaji Prague Open, působil jako manažer sekce tenis v rámci VICTORIA Vysokoškolského sportovního centra MŠMT\nlektorská činnost pro ČTS a PTS\nčlen výboru I. ČLTK Praha, Pražského tenisového svazu a Rady Českého tenisového svazu (člen Trenérsko-metodické komise PTS a ČTS)\núčastník řady tuzemských a zahraničních vědeckých konferencí se zaměřením na sportovní trénink\nod roku 2008 trenérem v I. ČLTK Praha\nod roku 2015 člen reprezentačních výjezdů ČTS\nspolupracoval s úspěšnými hráči (např. Jonáš Forejtek, Andrew Paulson, Darja Viďmanova, Nikola Bartůňková)', '', '+420 721 663 118', 'pecha@cltk.cz', '', 1, 0, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(16, 'Andrea Vašíčková', 'zástupce vedoucího trenéra tenisové školy', 'skola', '', 'treneri/andrea-vasickova.jpg', '50% 22%', 'koordinátorka sběračů při Prague Open 2022-24\ntrenér II. třídy ČTS\ndva roky působila jako trenér kategorie U10 v TK Sparta Praha, od roku 2009 v I. ČLTK Praha', '', '+420 602 819 899', '', '', 1, 1, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(17, 'Bc. Adéla Vašíčková', 'trenérka tenisové školy', 'skola', '', 'treneri/adela-vasickova.jpg', '50% 22%', 'absolventka bakalářského studia na UK FTVS (téma bakalářské práce: Vybrané somatické faktory u elitních hráčů a hráček tenisu)\ntrenér II. třídy ČTS\ntrenérka v I.ČLTK Praha od roku 2021\nbývalá ligová hráčka ČTS, vítězka dvouhry přeborů Prahy ve všech věkových kategoriích do 18 let, přední hráčka celostátního žebříčku ČTS v kategoriích do 12 let (CŽ 5), 14 let (CŽ 11) a 18 let (CŽ 15)\nčlenka české reprezentace v padelu', '', '+420 725 480 412', '', '', 1, 2, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(18, 'Berenika Urbanová', 'asist. trenérka tenisové školy', 'skola', '', '', '50% 22%', '', '', '', '', '', 1, 3, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(19, 'Ondřej Macek', 'privátní trenér pro rekreační hráče', 'privatni', 'Privátní trenéři pro rekreační hráče', '', '50% 22%', 'rok narození 1971\npraxe 30 let\nčeština, angličtina, němčina, ruština', '', '', '', '', 1, 0, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(20, 'Jan Pavlíček', 'privátní trenér pro rekreační hráče', 'privatni', 'Privátní trenéři pro rekreační hráče', '', '50% 22%', 'rok narození 1986\npraxe 15 let\nbývalý ligový hráč', '', '', '', '', 1, 1, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(21, 'Roman Bicek', 'privátní trenér pro rekreační hráče', 'privatni', 'Privátní trenéři pro rekreační hráče', '', '50% 22%', 'rok narození 1986\nbývalý ligový hráč', '', '', '', '', 1, 2, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(22, 'Jan Kurz', 'privátní trenér pro rekreační hráče', 'privatni', 'Privátní trenéři pro rekreační hráče', '', '50% 22%', 'rok narození 1944\npraxe přes 50 let\nbývalý ligový hráč; bývalý kouč Heleny Sukové (Revue 01/2026)', '', '', '', '', 1, 3, '2026-10-01 23:46:40', '2026-10-01 23:46:40'),
(23, 'Jiří Hřebec', 'privátní trenér pro rekreační hráče', 'privatni', 'Privátní trenéři pro rekreační hráče', 'treneri/jiri-hrebec.jpg', '50% 22%', 'trenér II. třídy\nbývalý československý reprezentant, top ranking 25 (19.4.1974)\nvítěz Galeova poháru (1970), účastník 17 zápasů v Davis Cupu (finalista z roku 1975)\nbývalý trenér Davis Cupu\nspolupracoval s úspěšnými hráči (např. Markéta Vondroušová, Iveta Benešová, Ivo Minář, Jan Hernych, Marek Routa, Robin Staněk, Vladislav Chramosta, Tomáš Cakl, Jaroslav Levinský)', '', '', '', '', 1, 4, '2026-10-01 23:46:40', '2026-10-01 23:46:40');
INSERT IGNORE INTO cltk_triptych (id, rok, jmeno, disciplina, foto, fokus, alt, vitez, souper, sety, hral_za, hral_za_text, visible, poradi) VALUES
(1, '1954', 'Jaroslav Drobný', 'Wimbledon · dvouhra mužů · finále', 'historie/triptych-1954-drobny.jpg', '50% 25%', 'Jaroslav Drobný s wimbledonským pohárem, 1954', 'Drobný', 'Rosewall', '[\"13:11\",\"4:6\",\"6:2\",\"9:7\"]', 'Egypt', 'Na Štvanici vyrostl jako syn správce, začínal jako sběrač míčků. Wimbledon vyhrál jako emigrant – a jako jediný muž v brýlích.', 1, 0),
(2, '1973', 'Jan Kodeš', 'Wimbledon · dvouhra mužů · finále', 'historie/triptych-1973-kodes.jpg', '50% 25%', 'Jan Kodeš s wimbledonským pohárem, 1973', 'Kodeš', 'Metreveli', '[\"6:1\",\"9:8 (7:5)\",\"6:3\"]', 'Sparta', 'Štvanický odchovanec, tehdy hráč Sparty. Trénoval ho štvanický Pavel Korda. Klubu později předsedal (1987–1990).', 1, 1),
(3, '2023', 'Markéta Vondroušová', 'Wimbledon · dvouhra žen · finále', 'historie/triptych-2023-vondrousova.jpg', '45% 30%', 'Markéta Vondroušová s mísou Venus Rosewater Dish, Wimbledon 2023', 'Vondroušová', 'Jabeurová', '[\"6:4\",\"6:4\"]', 'I. ČLTK Praha', 'Na Štvanici od roku 2006, za klub registrována od sezóny 2011. První nenasazená vítězka Wimbledonu v historii.', 1, 2);
