(1, '2026-09-27', 'Šen-čen', 'Billie Jean King Cup · finále · Česko – Ukrajina 2:0', 'Karolína Muchová', 'Anhelina Kalininová', 'V úvodní dvouhře finále porazila Anhelinu Kalininovou. Česko získalo dvanáctý titul v soutěži.', '[\"6:2\",\"6:3\"]', 'Titul', '', '', 1, 0, '2026-10-01 23:46:39', '2026-10-01 23:46:39'),
(2, '2026-08-27', 'New York', 'US Open · finále · smíšená čtyřhra', 'Karolína Muchová a Jakub Menšík', 'Belinda Bencicová, Flavio Cobolli', 'Česká dvojice získala senzační grandslamový titul, když ve finále porazila švýcarsko-italský pár Bencicová, Cobolli.', '[\"6:3\",\"1:6\",\"10:6\"]', 'Titul', 'https://cltk.cz/cs/clanky/karolina-muchova-ovladla-smisenou-ctyrhru-na-us-open:385/', '', 1, 1, '2026-10-01 23:46:39', '2026-10-01 23:46:39'),
(3, '2026-08-02', 'Memphis', 'WTA 250 Memphis · finále', 'Darja Viďmanová', 'Kristina Liutová', 'Finále s Kristinou Liutovou a posun do elitní stovky.', '[\"6:1\",\"1:6\",\"3:6\"]', 'Finále', 'https://cltk.cz/cs/clanky/darja-vidmanova-ve-finale-turnaje-wta-250-v-memphisu:383/', '', 1, 2, '2026-10-01 23:46:39', '2026-10-01 23:46:39'),
(4, '2026-07-11', 'Londýn', 'Wimbledon · finále · dvouhra žen', 'Karolína Muchová', 'Linda Nosková', 'První ryze české finále ženské dvouhry ve Wimbledonu. Dva dny nato kariérní maximum – 6. místo žebříčku WTA.', '[\"2:6\",\"7:5\",\"3:6\"]', 'Finále', 'https://cltk.cz/cs/clanky/karolina-muchova-ve-finale-wimbledonu:381/', '', 1, 3, '2026-10-01 23:46:39', '2026-10-01 23:46:39'),
(5, '2026-06-27', 'Bad Homburg', 'WTA 500 Bad Homburg · finále · tráva', 'Karolína Muchová', 'Naomi Osaka', 'Ve finále vedla 6:1, 1:0, když Naomi Osaka skrečovala. Premiérový titul na trávě a návrat do elitní desítky.', '[\"6:1\",\"1:0 skr.\"]', 'Titul', 'https://cltk.cz/cs/clanky/karolina-muchova-ziskala-titul-na-wta-premier-500-v-bad-homburgu:377/', '', 1, 4, '2026-10-01 23:46:39', '2026-10-01 23:46:39'),
(6, '2026-06-21', 'Figueira da Foz', 'WTA 125 Figueira da Foz · finále', 'Darja Viďmanová', 'Ayla Aksuová', 'Ve finále porazila Turkyni Aylu Aksuovou. První titul z okruhu WTA.', '[\"6:2\",\"6:3\"]', 'Titul', 'https://cltk.cz/cs/clanky/darja-vidmanova-ma-prvni-titul-z-wta:375/', '', 1, 5, '2026-10-01 23:46:39', '2026-10-01 23:46:39'),
(7, '2026-02-15', 'Praha', 'ITF W75 Conseq Prague Open · finále · Štvanice', 'Tereza Martincová', 'Sinja Krausová', 'Doma na Štvanici prošla z kvalifikace až k titulu, ve finále porazila nejvýše nasazenou Sinju Krausovou.', '[\"6:3\",\"6:4\"]', 'Titul', 'https://cltk.cz/cs/clanky/tereza-martincova-ovladla-conseq-prague-open-26:363/', '', 1, 6, '2026-10-01 23:46:39', '2026-10-01 23:46:39'),
(8, '2026-02-14', 'Dauhá', 'WTA 1000 Dauhá · finále', 'Karolína Muchová', 'Victoria Mboko', 'Ve finále porazila Kanaďanku Victorii Mboko a získala dosud největší titul kariéry.', '[\"6:4\",\"7:5\"]', 'Titul', 'https://cltk.cz/cs/clanky/karolina-muchova-vyhrala-tisicovku-v-dauha:364/', '', 1, 7, '2026-10-01 23:46:39', '2026-10-01 23:46:39');
